package com.tripchecklist;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(TripChecklistConfig.GROUP)
public interface TripChecklistConfig extends Config
{
	String GROUP = "tripchecklist";
	String KEY_SHOW_OPTIONAL_IN_PANEL = "showOptionalItemsInPanel";

	enum OnReadyBehavior
	{
		AUTO_CLOSE_ON_BANK_CLOSE("On bank close"),
		MANUAL_ONLY("Manual button only"),
		AUTO_CLOSE_IMMEDIATELY("Immediately when ready");

		private final String label;

		OnReadyBehavior(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigSection(
		name = "Bank Highlighting",
		description = "Highlight missing checklist items inside the open bank interface",
		position = 0
	)
	String bankSection = "bankSection";

	@ConfigSection(
		name = "HUD Overlay",
		description = "Compact on-screen readiness summary",
		position = 1
	)
	String hudSection = "hudSection";

	@ConfigSection(
		name = "Capture & Panel",
		description = "Loadout snapshot and sidebar display behavior",
		position = 2
	)
	String behaviorSection = "behaviorSection";

	@ConfigItem(
		keyName = "highlightBankItems",
		name = "Highlight missing items in bank",
		description = "Outline missing required items (and matching item groups) inside your open bank",
		section = bankSection,
		position = 0
	)
	default boolean highlightBankItems()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightOptionalBankItems",
		name = "Highlight optional items in bank",
		description = "Also outline unsatisfied optional checklist items in the open bank",
		section = bankSection,
		position = 1
	)
	default boolean highlightOptionalBankItems()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showBankMissingQuantity",
		name = "Show missing quantity badge",
		description = "Draw a compact -N badge on highlighted bank items showing how many are still needed",
		section = bankSection,
		position = 2
	)
	default boolean showBankMissingQuantity()
	{
		return true;
	}

	@ConfigItem(
		keyName = "bankRequiredColor",
		name = "Required item highlight",
		description = "Highlight color for missing required items in the bank",
		section = bankSection,
		position = 3
	)
	default Color bankRequiredColor()
	{
		return new Color(240, 180, 41);
	}

	@ConfigItem(
		keyName = "bankOptionalColor",
		name = "Optional item highlight",
		description = "Highlight color for missing optional items in the bank",
		section = bankSection,
		position = 4
	)
	default Color bankOptionalColor()
	{
		return new Color(88, 166, 255);
	}

	@ConfigItem(
		keyName = "highlightBestOwnedOnly",
		name = "Highlight only best usable item in bank",
		description = "For item groups, highlight only your highest-tier usable item owned in bank instead of lower-tier duplicates",
		section = bankSection,
		position = 5
	)
	default boolean highlightBestOwnedOnly()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showHudOverlay",
		name = "Show readiness HUD",
		description = "Display a compact on-screen HUD for the active checklist",
		section = hudSection,
		position = 0
	)
	default boolean showHudOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hudOnlyAtBank",
		name = "Show HUD only while bank is open",
		description = "Hide the on-screen HUD when the bank interface is closed",
		section = hudSection,
		position = 1
	)
	default boolean hudOnlyAtBank()
	{
		return false;
	}

	@ConfigItem(
		keyName = "autoHideHudWhenReady",
		name = "Auto-hide HUD when ready",
		description = "Hide the HUD once all required items and conditions are satisfied",
		section = hudSection,
		position = 2
	)
	default boolean autoHideHudWhenReady()
	{
		return false;
	}

	@Range(min = 3, max = 15)
	@ConfigItem(
		keyName = "hudMaxMissingRows",
		name = "Max missing rows in HUD",
		description = "Maximum number of missing items listed in the HUD before summarizing remaining items",
		section = hudSection,
		position = 3
	)
	default int hudMaxMissingRows()
	{
		return 8;
	}

	@ConfigItem(
		keyName = "collapseSmartGroupsOnCapture",
		name = "Smart-group captured items",
		description = "Automatically map captured potions, charged teleport jewelry, and tools to flexible item groups",
		section = behaviorSection,
		position = 0
	)
	default boolean collapseSmartGroupsOnCapture()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showOptionalItemsInPanel",
		name = "Show optional items in sidebar",
		description = "Display optional items inside the active checklist view",
		section = behaviorSection,
		position = 1
	)
	default boolean showOptionalItemsInPanel()
	{
		return true;
	}

	@ConfigItem(
		keyName = "onReadyBehavior",
		name = "Stop tracking when ready",
		description = "Choose whether tracking stops automatically when you close the bank while ready, immediately on becoming ready, or only via the sidebar button",
		section = behaviorSection,
		position = 2
	)
	default OnReadyBehavior onReadyBehavior()
	{
		return OnReadyBehavior.AUTO_CLOSE_ON_BANK_CLOSE;
	}
}

package com.tripchecklist;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.tripchecklist.data.BuiltInPresets;
import com.tripchecklist.data.ChecklistCategory;
import com.tripchecklist.data.PlayerLoadoutSnapshot;
import com.tripchecklist.data.TripChecklist;
import com.tripchecklist.logic.ChecklistEvaluator;
import com.tripchecklist.logic.ChecklistEvaluator.ChecklistEvaluation;
import com.tripchecklist.logic.ChecklistEvaluator.ItemEvaluation;
import com.tripchecklist.logic.ChecklistSerializer;
import com.tripchecklist.logic.LoadoutCapture;
import com.tripchecklist.overlay.BankChecklistOverlay;
import com.tripchecklist.overlay.TripHudOverlay;
import com.tripchecklist.ui.TripChecklistPanel;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.http.api.item.ItemPrice;

@PluginDescriptor(
	name = "Trip Checklist",
	description = "Account-aware pre-trip readiness checklists with BiS bank highlights, rune pouch, spellbook, charge warnings, and compact HUD",
	tags = {"checklist", "bank", "gear", "loadout", "inventory", "farm", "birdhouse", "bossing", "slayer", "clues", "skilling", "minigames", "supplies"}
)
public class TripChecklistPlugin extends Plugin
{
	private static final String KEY_CUSTOM_CHECKLISTS = "customChecklistsJson";
	private static final String KEY_ACTIVE_CHECKLIST_ID = "activeChecklistId";
	private static final String KEY_FAVORITES = "favoriteChecklists";
	private static final String KEY_BANK_CACHE_PREFIX = "bankCache_";

	private static final Set<Integer> TRACKED_VARBITS = new HashSet<>();

	static
	{
		TRACKED_VARBITS.add(VarbitID.SPELLBOOK);
		TRACKED_VARBITS.add(VarbitID.IRONMAN);
		TRACKED_VARBITS.add(VarbitID.RUNE_POUCH_TYPE_1);
		TRACKED_VARBITS.add(VarbitID.RUNE_POUCH_TYPE_2);
		TRACKED_VARBITS.add(VarbitID.RUNE_POUCH_TYPE_3);
		TRACKED_VARBITS.add(VarbitID.RUNE_POUCH_TYPE_4);
		TRACKED_VARBITS.add(VarbitID.RUNE_POUCH_TYPE_5);
		TRACKED_VARBITS.add(VarbitID.RUNE_POUCH_TYPE_6);
		TRACKED_VARBITS.add(VarbitID.RUNE_POUCH_QUANTITY_1);
		TRACKED_VARBITS.add(VarbitID.RUNE_POUCH_QUANTITY_2);
		TRACKED_VARBITS.add(VarbitID.RUNE_POUCH_QUANTITY_3);
		TRACKED_VARBITS.add(VarbitID.RUNE_POUCH_QUANTITY_4);
		TRACKED_VARBITS.add(VarbitID.RUNE_POUCH_QUANTITY_5);
		TRACKED_VARBITS.add(VarbitID.RUNE_POUCH_QUANTITY_6);
	}

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private Gson gson;

	@Inject
	private TripChecklistConfig config;

	@Inject
	private BankChecklistOverlay bankOverlay;

	@Inject
	private TripHudOverlay hudOverlay;

	private ChecklistSerializer serializer;
	private NavigationButton navButton;
	private TripChecklistPanel panel;

	private final List<TripChecklist> customChecklists = new ArrayList<>();
	private final Set<String> favoriteIds = new LinkedHashSet<>();
	private final Map<String, Set<String>> checkedRemindersByChecklist = new HashMap<>();
	private final Map<Integer, String> itemNameCache = new ConcurrentHashMap<>();

	private long loadedBankAccountHash = -1L;
	private Map<Integer, Integer> cachedBankCounts = Collections.emptyMap();
	private String lastPersistedBankEncoded = "";
	private volatile boolean wasBankOpen;
	private volatile boolean wasReadyForActive;
	@Nullable
	private volatile String lastEvaluatedChecklistId;

	@Nullable
	private volatile String activeChecklistId;

	@Getter
	private volatile PlayerLoadoutSnapshot latestSnapshot = PlayerLoadoutSnapshot.LOGGED_OUT;

	@Getter
	@Nullable
	private volatile ChecklistEvaluation activeEvaluation;

	@Provides
	TripChecklistConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TripChecklistConfig.class);
	}

	@Override
	protected void startUp()
	{
		serializer = new ChecklistSerializer(gson);
		loadPersistedState();

		panel = new TripChecklistPanel(this, config, configManager, itemManager);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/com/tripchecklist/icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Trip Checklist")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		overlayManager.add(bankOverlay);
		overlayManager.add(hudOverlay);

		clientThread.invokeLater(this::refreshSnapshotOnClientThread);
	}

	@Override
	protected void shutDown()
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		overlayManager.remove(bankOverlay);
		overlayManager.remove(hudOverlay);
		if (panel != null)
		{
			panel.dispose();
			panel = null;
		}
		latestSnapshot = PlayerLoadoutSnapshot.LOGGED_OUT;
		activeEvaluation = null;
		customChecklists.clear();
		favoriteIds.clear();
		checkedRemindersByChecklist.clear();
		itemNameCache.clear();
		cachedBankCounts = Collections.emptyMap();
		loadedBankAccountHash = -1L;
		lastPersistedBankEncoded = "";
		wasBankOpen = false;
		wasReadyForActive = false;
		lastEvaluatedChecklistId = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::refreshSnapshotOnClientThread);
		}
		else if (state == GameState.LOGIN_SCREEN)
		{
			latestSnapshot = PlayerLoadoutSnapshot.LOGGED_OUT;
			cachedBankCounts = Collections.emptyMap();
			loadedBankAccountHash = -1L;
			lastPersistedBankEncoded = "";
			wasBankOpen = false;
			wasReadyForActive = false;
			recomputeActiveEvaluation();
		}
		else if (state == GameState.HOPPING)
		{
			latestSnapshot = PlayerLoadoutSnapshot.LOGGED_OUT;
			wasBankOpen = false;
			wasReadyForActive = false;
			recomputeActiveEvaluation();
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id == InventoryID.INV || id == InventoryID.WORN || id == InventoryID.BANK)
		{
			refreshSnapshotOnClientThread();
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (TRACKED_VARBITS.contains(event.getVarbitId()) || event.getVarpId() == VarPlayerID.SA_ENERGY)
		{
			refreshSnapshotOnClientThread();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() == Skill.PRAYER || latestSnapshot.getSkillLevel(event.getSkill()) != event.getLevel())
		{
			refreshSnapshotOnClientThread();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		PlayerLoadoutSnapshot prev = latestSnapshot;
		Widget bankWidget = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		boolean bankOpenNow = bankWidget != null && !bankWidget.isHidden();
		int runPctNow = Math.min(100, Math.max(0, client.getEnergy() / 100));
		int specPctNow = Math.min(100, Math.max(0, client.getVarpValue(VarPlayerID.SA_ENERGY) / 10));

		if (!prev.isLoggedIn()
			|| prev.isBankOpen() != bankOpenNow
			|| prev.getRunEnergyPercent() != runPctNow
			|| prev.getSpecEnergyPercent() != specPctNow)
		{
			refreshSnapshotOnClientThread();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!TripChecklistConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		recomputeActiveEvaluation();
	}

	public synchronized List<TripChecklist> getAllChecklists()
	{
		List<TripChecklist> all = new ArrayList<>(customChecklists.size() + BuiltInPresets.all().size());
		all.addAll(customChecklists);
		all.addAll(BuiltInPresets.all());

		List<TripChecklist> ordered = new ArrayList<>(all.size());
		for (TripChecklist c : all)
		{
			if (favoriteIds.contains(c.getId()))
			{
				ordered.add(c);
			}
		}
		for (TripChecklist c : all)
		{
			if (!favoriteIds.contains(c.getId()))
			{
				ordered.add(c);
			}
		}
		return Collections.unmodifiableList(ordered);
	}

	public synchronized boolean isFavorite(@Nullable String checklistId)
	{
		return checklistId != null && favoriteIds.contains(checklistId);
	}

	public synchronized void toggleFavorite(@Nullable String checklistId)
	{
		if (checklistId == null || checklistId.isEmpty())
		{
			return;
		}
		if (!favoriteIds.remove(checklistId))
		{
			favoriteIds.add(checklistId);
		}
		persistFavorites();
		notifyPanel();
	}

	public synchronized void toggleReminder(String checklistId, String reminderText)
	{
		if (checklistId == null || reminderText == null)
		{
			return;
		}
		Set<String> checked = checkedRemindersByChecklist.computeIfAbsent(checklistId, k -> new HashSet<>());
		if (!checked.remove(reminderText))
		{
			checked.add(reminderText);
		}
		recomputeActiveEvaluation();
	}

	public synchronized void setAllRemindersChecked(String checklistId, boolean checked)
	{
		if (checklistId == null)
		{
			return;
		}
		TripChecklist checklist = findChecklistById(checklistId);
		if (checklist == null)
		{
			return;
		}
		if (!checked)
		{
			checkedRemindersByChecklist.remove(checklistId);
		}
		else
		{
			Set<String> set = checkedRemindersByChecklist.computeIfAbsent(checklistId, k -> new HashSet<>());
			if (checklist.getReminders() != null)
			{
				for (String rem : checklist.getReminders())
				{
					if (rem != null && !rem.trim().isEmpty())
					{
						set.add(rem.trim());
					}
				}
			}
		}
		recomputeActiveEvaluation();
	}

	@Nullable
	public synchronized TripChecklist findChecklistById(@Nullable String id)
	{
		if (id == null || id.isEmpty())
		{
			return null;
		}
		for (TripChecklist custom : customChecklists)
		{
			if (id.equals(custom.getId()))
			{
				return custom;
			}
		}
		for (TripChecklist preset : BuiltInPresets.all())
		{
			if (id.equals(preset.getId()))
			{
				return preset;
			}
		}
		return null;
	}

	@Nullable
	public String getActiveChecklistId()
	{
		return activeChecklistId;
	}

	public void selectChecklist(@Nullable String checklistId)
	{
		TripChecklist found = findChecklistById(checklistId);
		activeChecklistId = found != null ? found.getId() : null;
		if (activeChecklistId != null)
		{
			configManager.setConfiguration(TripChecklistConfig.GROUP, KEY_ACTIVE_CHECKLIST_ID, activeChecklistId);
		}
		else
		{
			configManager.unsetConfiguration(TripChecklistConfig.GROUP, KEY_ACTIVE_CHECKLIST_ID);
		}
		recomputeActiveEvaluation();
	}

	public void clearActiveChecklist()
	{
		selectChecklist(null);
	}

	public void completeActiveChecklist()
	{
		TripChecklist active = findChecklistById(activeChecklistId);
		if (active == null)
		{
			return;
		}
		String completedName = active.getName();
		synchronized (this)
		{
			checkedRemindersByChecklist.remove(active.getId());
		}
		activeChecklistId = null;
		activeEvaluation = null;
		wasReadyForActive = false;
		lastEvaluatedChecklistId = null;
		configManager.unsetConfiguration(TripChecklistConfig.GROUP, KEY_ACTIVE_CHECKLIST_ID);

		TripChecklistPanel currentPanel = panel;
		if (currentPanel != null)
		{
			SwingUtilities.invokeLater(() ->
			{
				currentPanel.refresh();
				currentPanel.showToastMessage("Ready - stopped tracking " + completedName);
			});
		}
	}

	public static boolean shouldAutoComplete(
		TripChecklistConfig.OnReadyBehavior behavior,
		boolean wasBankOpen,
		boolean isBankOpen,
		boolean wasReady,
		boolean isReady)
	{
		if (!isReady || behavior == null || behavior == TripChecklistConfig.OnReadyBehavior.MANUAL_ONLY)
		{
			return false;
		}
		if (behavior == TripChecklistConfig.OnReadyBehavior.AUTO_CLOSE_ON_BANK_CLOSE)
		{
			return wasBankOpen && !isBankOpen;
		}
		return behavior == TripChecklistConfig.OnReadyBehavior.AUTO_CLOSE_IMMEDIATELY && !wasReady;
	}

	public synchronized void saveCustomChecklist(TripChecklist checklist)
	{
		if (checklist == null || checklist.isBuiltIn())
		{
			return;
		}
		int replaceIndex = -1;
		for (int i = 0; i < customChecklists.size(); i++)
		{
			if (customChecklists.get(i).getId().equals(checklist.getId()))
			{
				replaceIndex = i;
				break;
			}
		}
		if (replaceIndex >= 0)
		{
			customChecklists.set(replaceIndex, checklist);
		}
		else
		{
			customChecklists.add(0, checklist);
		}
		persistCustomChecklists();
		activeChecklistId = checklist.getId();
		configManager.setConfiguration(TripChecklistConfig.GROUP, KEY_ACTIVE_CHECKLIST_ID, activeChecklistId);
		recomputeActiveEvaluation();
	}

	public synchronized void deleteCustomChecklist(String id)
	{
		if (id == null)
		{
			return;
		}
		boolean removed = customChecklists.removeIf(c -> id.equals(c.getId()));
		if (!removed)
		{
			return;
		}
		favoriteIds.remove(id);
		checkedRemindersByChecklist.remove(id);
		persistCustomChecklists();
		persistFavorites();
		if (id.equals(activeChecklistId))
		{
			activeChecklistId = null;
			configManager.unsetConfiguration(TripChecklistConfig.GROUP, KEY_ACTIVE_CHECKLIST_ID);
		}
		recomputeActiveEvaluation();
	}

	public String exportChecklistJson(TripChecklist checklist)
	{
		return serializer.exportSingleJson(checklist);
	}

	public TripChecklist importChecklistJson(String json)
	{
		TripChecklist imported = serializer.importSingleJson(json);
		saveCustomChecklist(imported);
		return imported;
	}

	public void captureCurrentLoadout(String name, ChecklistCategory category, Consumer<TripChecklist> onCaptured)
	{
		clientThread.invokeLater(() ->
		{
			refreshSnapshotOnClientThread();
			TripChecklist captured = LoadoutCapture.capture(
				name,
				category,
				latestSnapshot,
				config.collapseSmartGroupsOnCapture(),
				this::resolveItemNameOnClientThread
			);
			saveCustomChecklist(captured);
			if (onCaptured != null)
			{
				SwingUtilities.invokeLater(() -> onCaptured.accept(captured));
			}
		});
	}

	public void searchItems(String query, Consumer<List<ItemPrice>> onResults)
	{
		String trimmed = query != null ? query.trim() : "";
		if (trimmed.length() < 2)
		{
			SwingUtilities.invokeLater(() -> onResults.accept(Collections.emptyList()));
			return;
		}
		clientThread.invokeLater(() ->
		{
			List<ItemPrice> hits = itemManager.search(trimmed);
			List<ItemPrice> limited = hits.size() > 25 ? new ArrayList<>(hits.subList(0, 25)) : new ArrayList<>(hits);
			SwingUtilities.invokeLater(() -> onResults.accept(limited));
		});
	}

	@Nullable
	public String getCachedItemName(int itemId)
	{
		return itemId > 0 ? itemNameCache.get(itemId) : null;
	}

	private String resolveItemNameOnClientThread(int itemId)
	{
		ItemComposition comp = itemManager.getItemComposition(itemId);
		String name = comp != null && comp.getName() != null ? comp.getName() : ("Item #" + itemId);
		itemNameCache.put(itemId, name);
		return name;
	}

	private void refreshSnapshotOnClientThread()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			latestSnapshot = PlayerLoadoutSnapshot.LOGGED_OUT;
			wasBankOpen = false;
			wasReadyForActive = false;
			recomputeActiveEvaluation();
			return;
		}

		long accountHash = client.getAccountHash();
		if (accountHash != -1L && accountHash != loadedBankAccountHash)
		{
			loadedBankAccountHash = accountHash;
			String bankKey = KEY_BANK_CACHE_PREFIX + Long.toUnsignedString(accountHash);
			String encoded = configManager.getConfiguration(TripChecklistConfig.GROUP, bankKey);
			cachedBankCounts = decodeBankCounts(encoded);
			lastPersistedBankEncoded = encoded != null ? encoded : "";
		}

		boolean prevBankOpen = wasBankOpen;
		PlayerLoadoutSnapshot snapshot = PlayerLoadoutSnapshot.fromClient(client, itemManager, cachedBankCounts);
		latestSnapshot = snapshot;
		wasBankOpen = snapshot.isBankOpen();

		ItemContainer liveBankContainer = client.getItemContainer(InventoryID.BANK);
		if (liveBankContainer != null && liveBankContainer.getItems() != null && liveBankContainer.getItems().length > 0
			&& !snapshot.isUltimateIronman() && accountHash != -1L)
		{
			cachedBankCounts = snapshot.getBankCounts();
			String encodedNow = encodeBankCounts(cachedBankCounts);
			if (!encodedNow.equals(lastPersistedBankEncoded))
			{
				lastPersistedBankEncoded = encodedNow;
				String bankKey = KEY_BANK_CACHE_PREFIX + Long.toUnsignedString(accountHash);
				configManager.setConfiguration(TripChecklistConfig.GROUP, bankKey, encodedNow);
			}
		}

		recomputeActiveEvaluation(prevBankOpen, snapshot.isBankOpen());
	}

	private void recomputeActiveEvaluation()
	{
		boolean bankOpenNow = latestSnapshot != null && latestSnapshot.isBankOpen();
		recomputeActiveEvaluation(bankOpenNow, bankOpenNow);
	}

	private void recomputeActiveEvaluation(boolean prevBankOpen, boolean isBankOpenNow)
	{
		TripChecklist active = findChecklistById(activeChecklistId);
		if (active == null)
		{
			activeEvaluation = null;
			wasReadyForActive = false;
			lastEvaluatedChecklistId = null;
			notifyPanel();
			return;
		}
		Set<String> checked;
		synchronized (this)
		{
			Set<String> stored = checkedRemindersByChecklist.get(active.getId());
			checked = stored != null ? new HashSet<>(stored) : Collections.emptySet();
		}

		ChecklistEvaluation evaluated = ChecklistEvaluator.evaluate(
			active,
			latestSnapshot,
			config.highlightBestOwnedOnly(),
			checked
		);

		boolean sameChecklist = active.getId().equals(lastEvaluatedChecklistId);
		boolean prevReady = sameChecklist ? wasReadyForActive : evaluated.isReady();
		lastEvaluatedChecklistId = active.getId();
		wasReadyForActive = evaluated.isReady();

		if (shouldAutoComplete(config.onReadyBehavior(), prevBankOpen, isBankOpenNow, prevReady, evaluated.isReady()))
		{
			completeActiveChecklist();
			return;
		}

		activeEvaluation = evaluated;

		List<Integer> uncachedIds = new ArrayList<>();
		for (ItemEvaluation itemEval : evaluated.getItems())
		{
			int recId = itemEval.getRecommendedItemId();
			if (recId > 0 && !itemNameCache.containsKey(recId))
			{
				uncachedIds.add(recId);
			}
		}
		if (!uncachedIds.isEmpty())
		{
			clientThread.invokeLater(() ->
			{
				for (int id : uncachedIds)
				{
					resolveItemNameOnClientThread(id);
				}
				notifyPanel();
			});
		}
		notifyPanel();
	}

	private void notifyPanel()
	{
		TripChecklistPanel currentPanel = panel;
		if (currentPanel != null)
		{
			SwingUtilities.invokeLater(currentPanel::refresh);
		}
	}

	private synchronized void loadPersistedState()
	{
		customChecklists.clear();
		String savedJson = configManager.getConfiguration(TripChecklistConfig.GROUP, KEY_CUSTOM_CHECKLISTS);
		customChecklists.addAll(serializer.deserializeCustomList(savedJson));

		favoriteIds.clear();
		String savedFavs = configManager.getConfiguration(TripChecklistConfig.GROUP, KEY_FAVORITES);
		if (savedFavs != null && !savedFavs.isEmpty())
		{
			for (String token : savedFavs.split(","))
			{
				String trimmed = token.trim();
				if (!trimmed.isEmpty())
				{
					favoriteIds.add(trimmed);
				}
			}
		}

		String savedActiveId = configManager.getConfiguration(TripChecklistConfig.GROUP, KEY_ACTIVE_CHECKLIST_ID);
		activeChecklistId = findChecklistById(savedActiveId) != null ? savedActiveId : null;
	}

	private void persistCustomChecklists()
	{
		String json = serializer.serializeCustomList(customChecklists);
		configManager.setConfiguration(TripChecklistConfig.GROUP, KEY_CUSTOM_CHECKLISTS, json);
	}

	private void persistFavorites()
	{
		configManager.setConfiguration(TripChecklistConfig.GROUP, KEY_FAVORITES, String.join(",", favoriteIds));
	}

	public static String encodeBankCounts(Map<Integer, Integer> counts)
	{
		if (counts == null || counts.isEmpty())
		{
			return "";
		}
		List<Integer> sortedIds = new ArrayList<>(counts.keySet());
		Collections.sort(sortedIds);
		StringBuilder sb = new StringBuilder(sortedIds.size() * 10);
		for (int id : sortedIds)
		{
			int qty = counts.getOrDefault(id, 0);
			if (id <= 0 || qty <= 0)
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(',');
			}
			sb.append(id).append(':').append(qty);
		}
		return sb.toString();
	}

	public static Map<Integer, Integer> decodeBankCounts(@Nullable String encoded)
	{
		if (encoded == null || encoded.trim().isEmpty())
		{
			return Collections.emptyMap();
		}
		Map<Integer, Integer> map = new HashMap<>();
		for (String entry : encoded.split(","))
		{
			int sep = entry.indexOf(':');
			if (sep <= 0 || sep >= entry.length() - 1)
			{
				continue;
			}
			try
			{
				int id = Integer.parseInt(entry.substring(0, sep));
				int qty = Integer.parseInt(entry.substring(sep + 1));
				if (id > 0 && qty > 0)
				{
					map.put(id, qty);
				}
			}
			catch (NumberFormatException ignored)
			{
				// Skip malformed entry
			}
		}
		return map.isEmpty() ? Collections.emptyMap() : Collections.unmodifiableMap(map);
	}
}

