package com.tripchecklist.data;

import java.util.Collections;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@Builder(toBuilder = true)
@NoArgsConstructor
@AllArgsConstructor
public class ChecklistItem
{
	private String label;
	private int itemId;
	@Nullable
	private String groupId;
	@Builder.Default
	private int quantity = 1;
	@Builder.Default
	private ItemSlotScope scope = ItemSlotScope.ANY;
	private boolean optional;
	private boolean checkRunePouch;

	@Nullable
	public ItemGroup resolveGroup()
	{
		return ItemGroup.fromName(groupId);
	}

	public int getDisplayIconId()
	{
		if (itemId > 0)
		{
			return itemId;
		}
		ItemGroup group = resolveGroup();
		return group != null ? group.getIconItemId() : -1;
	}

	public Set<Integer> getMatchingItemIds()
	{
		ItemGroup group = resolveGroup();
		if (group != null)
		{
			return group.getItemIds();
		}
		return itemId > 0 ? Collections.singleton(itemId) : Collections.emptySet();
	}

	public static ChecklistItem exact(String label, int itemId, int quantity, ItemSlotScope scope, boolean optional)
	{
		return ChecklistItem.builder()
			.label(label)
			.itemId(itemId)
			.quantity(Math.max(1, quantity))
			.scope(scope != null ? scope : ItemSlotScope.ANY)
			.optional(optional)
			.build();
	}

	public static ChecklistItem rune(String label, int runeItemId, int quantity, boolean optional)
	{
		return ChecklistItem.builder()
			.label(label)
			.itemId(runeItemId)
			.quantity(Math.max(1, quantity))
			.scope(ItemSlotScope.INVENTORY)
			.optional(optional)
			.checkRunePouch(true)
			.build();
	}

	public static ChecklistItem group(String label, ItemGroup group, int quantity, ItemSlotScope scope, boolean optional)
	{
		return ChecklistItem.builder()
			.label(label != null && !label.isEmpty() ? label : group.getDisplayName())
			.itemId(group.getIconItemId())
			.groupId(group.name())
			.quantity(Math.max(1, quantity))
			.scope(scope != null ? scope : ItemSlotScope.ANY)
			.optional(optional)
			.build();
	}
}

