package com.tripchecklist.data;

import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.Builder;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;

@Value
@Builder
public class PlayerLoadoutSnapshot
{
	public static final int INVENTORY_CAPACITY = 28;

	public enum IronmanType
	{
		NORMAL(""),
		IRONMAN("IM"),
		ULTIMATE_IRONMAN("UIM"),
		HARDCORE_IRONMAN("HCIM"),
		GROUP_IRONMAN("GIM"),
		HARDCORE_GROUP_IRONMAN("HCGIM");

		private final String shortLabel;

		IronmanType(String shortLabel)
		{
			this.shortLabel = shortLabel;
		}

		public String getShortLabel()
		{
			return shortLabel;
		}
	}

	private static final int[] RUNE_POUCH_TYPE_VARBITS = {
		VarbitID.RUNE_POUCH_TYPE_1,
		VarbitID.RUNE_POUCH_TYPE_2,
		VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4,
		VarbitID.RUNE_POUCH_TYPE_5,
		VarbitID.RUNE_POUCH_TYPE_6
	};

	private static final int[] RUNE_POUCH_QTY_VARBITS = {
		VarbitID.RUNE_POUCH_QUANTITY_1,
		VarbitID.RUNE_POUCH_QUANTITY_2,
		VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4,
		VarbitID.RUNE_POUCH_QUANTITY_5,
		VarbitID.RUNE_POUCH_QUANTITY_6
	};

	public static final PlayerLoadoutSnapshot LOGGED_OUT = PlayerLoadoutSnapshot.builder()
		.loggedIn(false)
		.membersWorld(true)
		.bankOpen(false)
		.accountHash(-1L)
		.accountType(IronmanType.NORMAL)
		.activeSpellbook(SpellbookType.STANDARD)
		.prayerPercent(100)
		.runEnergyPercent(100)
		.specEnergyPercent(100)
		.freeInventorySlots(INVENTORY_CAPACITY)
		.equippedWeaponId(-1)
		.equippedAmmoId(-1)
		.skillLevels(Collections.emptyMap())
		.inventoryCounts(Collections.emptyMap())
		.equipmentCounts(Collections.emptyMap())
		.runePouchCounts(Collections.emptyMap())
		.bankCounts(Collections.emptyMap())
		.build();

	boolean loggedIn;
	@Builder.Default
	boolean membersWorld = true;
	boolean bankOpen;
	long accountHash;
	@Builder.Default
	IronmanType accountType = IronmanType.NORMAL;
	@Builder.Default
	SpellbookType activeSpellbook = SpellbookType.STANDARD;
	int prayerPercent;
	int runEnergyPercent;
	int specEnergyPercent;
	@Builder.Default
	int freeInventorySlots = INVENTORY_CAPACITY;
	@Builder.Default
	int equippedWeaponId = -1;
	@Builder.Default
	int equippedAmmoId = -1;
	@Builder.Default
	Map<Skill, Integer> skillLevels = Collections.emptyMap();
	@Builder.Default
	Map<Integer, Integer> inventoryCounts = Collections.emptyMap();
	@Builder.Default
	Map<Integer, Integer> equipmentCounts = Collections.emptyMap();
	@Builder.Default
	Map<Integer, Integer> runePouchCounts = Collections.emptyMap();
	@Builder.Default
	Map<Integer, Integer> bankCounts = Collections.emptyMap();

	public boolean isUltimateIronman()
	{
		return accountType == IronmanType.ULTIMATE_IRONMAN;
	}

	public String getAccountTypeShortLabel()
	{
		return accountType != null ? accountType.getShortLabel() : "";
	}

	public int getSkillLevel(Skill skill)
	{
		if (!loggedIn || skill == null || skillLevels == null)
		{
			return 99;
		}
		return skillLevels.getOrDefault(skill, 1);
	}

	public boolean hasRunePouchCarried()
	{
		for (int pouchId : ItemGroup.RUNE_POUCH.getItemIds())
		{
			if (inventoryCounts.getOrDefault(pouchId, 0) > 0)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Must be called on the RuneLite client thread.
	 */
	public static PlayerLoadoutSnapshot fromClient(Client client, ItemManager itemManager)
	{
		return fromClient(client, itemManager, Collections.emptyMap());
	}

	/**
	 * Must be called on the RuneLite client thread.
	 */
	public static PlayerLoadoutSnapshot fromClient(
		Client client,
		ItemManager itemManager,
		@Nullable Map<Integer, Integer> cachedBankFallback)
	{
		if (client == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return LOGGED_OUT;
		}

		ItemContainer invContainer = client.getItemContainer(InventoryID.INV);
		ItemContainer wornContainer = client.getItemContainer(InventoryID.WORN);
		ItemContainer bankContainer = client.getItemContainer(InventoryID.BANK);

		Map<Integer, Integer> inv = readContainer(invContainer, itemManager);
		Map<Integer, Integer> worn = readContainer(wornContainer, itemManager);
		Map<Integer, Integer> liveBank = readContainer(bankContainer, itemManager);

		IronmanType accountType = decodeAccountType(client.getVarbitValue(VarbitID.IRONMAN));
		Map<Integer, Integer> effectiveBank;
		if (accountType == IronmanType.ULTIMATE_IRONMAN)
		{
			effectiveBank = Collections.emptyMap();
		}
		else if (!liveBank.isEmpty())
		{
			effectiveBank = liveBank;
		}
		else if (cachedBankFallback != null && !cachedBankFallback.isEmpty())
		{
			effectiveBank = new HashMap<>(cachedBankFallback);
		}
		else
		{
			effectiveBank = Collections.emptyMap();
		}

		int occupiedInvSlots = countOccupiedSlots(invContainer);
		int freeSlots = Math.max(0, INVENTORY_CAPACITY - occupiedInvSlots);
		int weaponId = readSlotItemId(wornContainer, EquipmentInventorySlot.WEAPON, itemManager);
		int ammoId = readSlotItemId(wornContainer, EquipmentInventorySlot.AMMO, itemManager);

		Widget bankWidget = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		boolean bankOpen = bankWidget != null && !bankWidget.isHidden();

		Map<Integer, Integer> pouchRunes = Collections.emptyMap();
		boolean carryingPouch = false;
		for (int pouchId : ItemGroup.RUNE_POUCH.getItemIds())
		{
			if (inv.getOrDefault(pouchId, 0) > 0)
			{
				carryingPouch = true;
				break;
			}
		}
		// Rune Pouch varbits retain contents even while banked, so only count pouch runes when carried.
		if (carryingPouch)
		{
			pouchRunes = readRunePouchRunes(client);
		}

		Map<Skill, Integer> skills = new EnumMap<>(Skill.class);
		for (Skill skill : Skill.values())
		{
			if (!"Overall".equalsIgnoreCase(skill.getName()))
			{
				skills.put(skill, client.getRealSkillLevel(skill));
			}
		}

		int realPrayer = client.getRealSkillLevel(Skill.PRAYER);
		int boostedPrayer = client.getBoostedSkillLevel(Skill.PRAYER);
		int prayerPct = realPrayer > 0 ? Math.min(100, Math.max(0, (boostedPrayer * 100) / realPrayer)) : 100;
		int runPct = Math.min(100, Math.max(0, client.getEnergy() / 100));
		int specPct = Math.min(100, Math.max(0, client.getVarpValue(VarPlayerID.SA_ENERGY) / 10));
		boolean members = client.getWorldType().contains(WorldType.MEMBERS);

		return PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(members)
			.bankOpen(bankOpen)
			.accountHash(client.getAccountHash())
			.accountType(accountType)
			.activeSpellbook(SpellbookType.fromVarbit(client.getVarbitValue(VarbitID.SPELLBOOK)))
			.prayerPercent(prayerPct)
			.runEnergyPercent(runPct)
			.specEnergyPercent(specPct)
			.freeInventorySlots(freeSlots)
			.equippedWeaponId(weaponId)
			.equippedAmmoId(ammoId)
			.skillLevels(Collections.unmodifiableMap(skills))
			.inventoryCounts(Collections.unmodifiableMap(inv))
			.equipmentCounts(Collections.unmodifiableMap(worn))
			.runePouchCounts(Collections.unmodifiableMap(pouchRunes))
			.bankCounts(Collections.unmodifiableMap(effectiveBank))
			.build();
	}

	private static int countOccupiedSlots(@Nullable ItemContainer container)
	{
		if (container == null || container.getItems() == null)
		{
			return 0;
		}
		int used = 0;
		for (Item item : container.getItems())
		{
			if (item != null && item.getId() > 0 && item.getQuantity() > 0)
			{
				used++;
			}
		}
		return used;
	}

	private static int readSlotItemId(@Nullable ItemContainer worn, EquipmentInventorySlot slot, @Nullable ItemManager itemManager)
	{
		if (worn == null)
		{
			return -1;
		}
		Item item = worn.getItem(slot.getSlotIdx());
		if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
		{
			return -1;
		}
		return itemManager != null ? itemManager.canonicalize(item.getId()) : item.getId();
	}

	private static Map<Integer, Integer> readContainer(@Nullable ItemContainer container, @Nullable ItemManager itemManager)
	{
		if (container == null)
		{
			return Collections.emptyMap();
		}
		Item[] items = container.getItems();
		if (items == null || items.length == 0)
		{
			return Collections.emptyMap();
		}
		Map<Integer, Integer> counts = new HashMap<>(items.length * 2);
		for (Item item : items)
		{
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			int canonicalId = itemManager != null ? itemManager.canonicalize(item.getId()) : item.getId();
			counts.merge(canonicalId, item.getQuantity(), Integer::sum);
		}
		return counts;
	}

	private static Map<Integer, Integer> readRunePouchRunes(Client client)
	{
		EnumComposition runeEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runeEnum == null)
		{
			return Collections.emptyMap();
		}
		Map<Integer, Integer> runes = new HashMap<>(8);
		for (int i = 0; i < RUNE_POUCH_TYPE_VARBITS.length; i++)
		{
			int typeId = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[i]);
			int qty = client.getVarbitValue(RUNE_POUCH_QTY_VARBITS[i]);
			if (typeId <= 0 || qty <= 0)
			{
				continue;
			}
			int runeItemId = runeEnum.getIntValue(typeId);
			if (runeItemId > 0)
			{
				runes.merge(runeItemId, qty, Integer::sum);
			}
		}
		return runes;
	}

	public static IronmanType decodeAccountType(int ironmanVarbit)
	{
		switch (ironmanVarbit)
		{
			case 1:
				return IronmanType.IRONMAN;
			case 2:
				return IronmanType.ULTIMATE_IRONMAN;
			case 3:
				return IronmanType.HARDCORE_IRONMAN;
			case 4:
			case 6:
				return IronmanType.GROUP_IRONMAN;
			case 5:
				return IronmanType.HARDCORE_GROUP_IRONMAN;
			default:
				return IronmanType.NORMAL;
		}
	}
}

