package com.tripchecklist.data;

import java.util.ArrayList;
import java.util.List;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@Builder(toBuilder = true)
@NoArgsConstructor
@AllArgsConstructor
public class TripChecklist
{
	private String id;
	private String name;
	@Builder.Default
	private ChecklistCategory category = ChecklistCategory.CUSTOM;
	private boolean builtIn;
	@Builder.Default
	private SpellbookType requiredSpellbook = SpellbookType.ANY;
	private int minPrayerPercent;
	private int minRunEnergy;
	private int minSpecPercent;
	private int minFreeSlots;
	private boolean checkRangedAmmo;
	@Builder.Default
	private String notes = "";
	@Builder.Default
	private List<ChecklistItem> items = new ArrayList<>();
	@Builder.Default
	private List<String> reminders = new ArrayList<>();

	public TripChecklist copyAsCustom(String newId, String newName)
	{
		List<ChecklistItem> copiedItems = new ArrayList<>(items != null ? items.size() : 0);
		if (items != null)
		{
			for (ChecklistItem item : items)
			{
				copiedItems.add(item.toBuilder().build());
			}
		}
		List<String> copiedReminders = reminders != null ? new ArrayList<>(reminders) : new ArrayList<>();
		return TripChecklist.builder()
			.id(newId)
			.name(newName)
			.category(category != null ? category : ChecklistCategory.CUSTOM)
			.builtIn(false)
			.requiredSpellbook(requiredSpellbook != null ? requiredSpellbook : SpellbookType.ANY)
			.minPrayerPercent(minPrayerPercent)
			.minRunEnergy(minRunEnergy)
			.minSpecPercent(minSpecPercent)
			.minFreeSlots(minFreeSlots)
			.checkRangedAmmo(checkRangedAmmo)
			.notes(notes != null ? notes : "")
			.items(copiedItems)
			.reminders(copiedReminders)
			.build();
	}
}

package com.tripchecklist.logic;

import com.tripchecklist.data.ChecklistItem;
import com.tripchecklist.data.ItemGroup;
import com.tripchecklist.data.ItemSlotScope;
import com.tripchecklist.data.PlayerLoadoutSnapshot;
import com.tripchecklist.data.SpellbookType;
import com.tripchecklist.data.TripChecklist;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import lombok.Value;

public final class ChecklistEvaluator
{
	public enum ItemStatus
	{
		SATISFIED,
		PARTIAL,
		MISSING,
		OPTIONAL_MISSING
	}

	@Value
	public static class ItemEvaluation
	{
		ChecklistItem item;
		ItemStatus status;
		int ownedCount;
		int requiredCount;
		int inBankCount;
		boolean satisfiedByUnlimitedVariant;
		int recommendedItemId;
		boolean recommendedFromBank;

		public int getMissingCount()
		{
			return Math.max(0, requiredCount - ownedCount);
		}

		public boolean isSatisfied()
		{
			return status == ItemStatus.SATISFIED;
		}
	}

	@Value
	public static class ConditionCheck
	{
		String label;
		String currentValue;
		String expectedValue;
		boolean satisfied;
	}

	@Value
	public static class ReminderCheck
	{
		String text;
		boolean checked;
	}

	@Value
	public static class BankHighlightHint
	{
		String label;
		int missingCount;
		boolean optional;
	}

	@Value
	public static class ChecklistEvaluation
	{
		TripChecklist checklist;
		boolean loggedIn;
		boolean ready;
		int requiredSatisfied;
		int requiredTotal;
		int conditionsSatisfied;
		int conditionsTotal;
		int remindersChecked;
		int remindersTotal;
		List<ItemEvaluation> items;
		List<ConditionCheck> conditions;
		List<ReminderCheck> reminders;
		Map<Integer, BankHighlightHint> bankHighlightsByItemId;

		@Nullable
		public BankHighlightHint getBankHighlight(int canonicalItemId)
		{
			return bankHighlightsByItemId.get(canonicalItemId);
		}

		public int getMissingRequiredTotal()
		{
			return (requiredTotal - requiredSatisfied)
				+ (conditionsTotal - conditionsSatisfied)
				+ (remindersTotal - remindersChecked);
		}

		public List<ItemEvaluation> getItemsSortedMissingFirst()
		{
			List<ItemEvaluation> sorted = new ArrayList<>(items);
			sorted.sort(Comparator.comparingInt(ChecklistEvaluator::displayOrderRank));
			return sorted;
		}
	}

	private ChecklistEvaluator()
	{
	}

	public static ChecklistEvaluation evaluate(TripChecklist checklist, PlayerLoadoutSnapshot snapshot)
	{
		return evaluate(checklist, snapshot, true, Collections.emptySet());
	}

	public static ChecklistEvaluation evaluate(TripChecklist checklist, PlayerLoadoutSnapshot snapshot, boolean highlightBestOwnedOnly)
	{
		return evaluate(checklist, snapshot, highlightBestOwnedOnly, Collections.emptySet());
	}

	public static ChecklistEvaluation evaluate(
		TripChecklist checklist,
		PlayerLoadoutSnapshot snapshot,
		boolean highlightBestOwnedOnly,
		@Nullable Set<String> checkedReminders)
	{
		List<ChecklistItem> sourceItems = checklist.getItems() != null ? checklist.getItems() : Collections.emptyList();
		List<ItemEvaluation> itemEvals = new ArrayList<>(sourceItems.size());
		List<ConditionCheck> conditions = new ArrayList<>(8);
		List<ReminderCheck> reminderChecks = new ArrayList<>();
		Map<Integer, BankHighlightHint> bankHighlights = new HashMap<>();

		int reqTotal = 0;
		int reqSat = 0;

		for (ChecklistItem item : sourceItems)
		{
			int requiredQty = Math.max(1, item.getQuantity());
			if (!item.isOptional())
			{
				reqTotal++;
			}

			int owned = 0;
			int inBank = 0;
			boolean unlimitedSatisfied = false;
			int recommendedItemId = item.getDisplayIconId();
			boolean recommendedFromBank = false;
			ItemGroup group = item.resolveGroup();

			if (snapshot.isLoggedIn())
			{
				CountResult ownedResult = countMatching(item, snapshot);
				owned = ownedResult.count;
				unlimitedSatisfied = ownedResult.unlimitedSatisfied;

				if (group != null)
				{
					inBank = countUsableInBank(group, snapshot);
					int carriedBest = bestCarriedId(item, group, snapshot);
					if (carriedBest > 0)
					{
						recommendedItemId = carriedBest;
					}
					else
					{
						int bestBank = !snapshot.isUltimateIronman()
							? group.bestUsableInPool(snapshot, snapshot.getBankCounts())
							: -1;
						if (bestBank > 0)
						{
							recommendedItemId = bestBank;
							recommendedFromBank = true;
						}
						else
						{
							recommendedItemId = group.bestUsableTheoretical(snapshot);
						}
					}
				}
				else
				{
					inBank = countInMap(item, snapshot.getBankCounts()).count;
					if (owned <= 0 && !snapshot.isUltimateIronman() && inBank > 0)
					{
						recommendedFromBank = true;
					}
				}
			}

			int effectiveOwned = unlimitedSatisfied ? requiredQty : owned;
			ItemStatus status;
			if (!snapshot.isLoggedIn())
			{
				status = item.isOptional() ? ItemStatus.OPTIONAL_MISSING : ItemStatus.MISSING;
			}
			else if (effectiveOwned >= requiredQty)
			{
				status = ItemStatus.SATISFIED;
			}
			else if (effectiveOwned > 0)
			{
				status = item.isOptional() ? ItemStatus.OPTIONAL_MISSING : ItemStatus.PARTIAL;
			}
			else
			{
				status = item.isOptional() ? ItemStatus.OPTIONAL_MISSING : ItemStatus.MISSING;
			}

			if (!item.isOptional() && status == ItemStatus.SATISFIED)
			{
				reqSat++;
			}

			ItemEvaluation eval = new ItemEvaluation(
				item,
				status,
				effectiveOwned,
				requiredQty,
				inBank,
				unlimitedSatisfied,
				recommendedItemId,
				recommendedFromBank
			);
			itemEvals.add(eval);

			if (snapshot.isLoggedIn() && status != ItemStatus.SATISFIED)
			{
				int missingQty = eval.getMissingCount();
				BankHighlightHint hint = new BankHighlightHint(item.getLabel(), missingQty, item.isOptional());
				Set<Integer> excludeWorn = (item.getScope() == ItemSlotScope.EQUIPMENT && requiredQty > 1)
					? snapshot.getEquipmentCounts().keySet()
					: null;
				Iterable<Integer> targetIds = group != null
					? group.selectBestBankHighlightIds(snapshot, snapshot.getBankCounts(), excludeWorn, missingQty, highlightBestOwnedOnly)
					: item.getMatchingItemIds();

				for (int matchId : targetIds)
				{
					BankHighlightHint existing = bankHighlights.get(matchId);
					// Required highlights always take priority over optional highlights on the same item ID.
					if (existing == null || (existing.isOptional() && !hint.isOptional())
						|| (existing.isOptional() == hint.isOptional() && hint.getMissingCount() > existing.getMissingCount()))
					{
						bankHighlights.put(matchId, hint);
					}
				}
			}
		}

		if (checklist.getRequiredSpellbook() != null && checklist.getRequiredSpellbook() != SpellbookType.ANY)
		{
			boolean sat = snapshot.isLoggedIn() && snapshot.getActiveSpellbook() == checklist.getRequiredSpellbook();
			conditions.add(new ConditionCheck(
				"Spellbook",
				snapshot.isLoggedIn() ? snapshot.getActiveSpellbook().getDisplayName() : "Logged out",
				checklist.getRequiredSpellbook().getDisplayName(),
				sat
			));
		}

		if (checklist.getMinPrayerPercent() > 0)
		{
			boolean sat = snapshot.isLoggedIn() && snapshot.getPrayerPercent() >= checklist.getMinPrayerPercent();
			conditions.add(new ConditionCheck(
				"Prayer",
				snapshot.isLoggedIn() ? snapshot.getPrayerPercent() + "%" : "Logged out",
				">= " + checklist.getMinPrayerPercent() + "%",
				sat
			));
		}

		if (checklist.getMinRunEnergy() > 0)
		{
			boolean sat = snapshot.isLoggedIn() && snapshot.getRunEnergyPercent() >= checklist.getMinRunEnergy();
			conditions.add(new ConditionCheck(
				"Run Energy",
				snapshot.isLoggedIn() ? snapshot.getRunEnergyPercent() + "%" : "Logged out",
				">= " + checklist.getMinRunEnergy() + "%",
				sat
			));
		}

		if (checklist.getMinSpecPercent() > 0)
		{
			boolean sat = snapshot.isLoggedIn() && snapshot.getSpecEnergyPercent() >= checklist.getMinSpecPercent();
			conditions.add(new ConditionCheck(
				"Special Attack",
				snapshot.isLoggedIn() ? snapshot.getSpecEnergyPercent() + "%" : "Logged out",
				">= " + checklist.getMinSpecPercent() + "%",
				sat
			));
		}

		if (checklist.getMinFreeSlots() > 0)
		{
			boolean sat = snapshot.isLoggedIn() && snapshot.getFreeInventorySlots() >= checklist.getMinFreeSlots();
			conditions.add(new ConditionCheck(
				"Free Inv Slots",
				snapshot.isLoggedIn() ? snapshot.getFreeInventorySlots() + " free" : "Logged out",
				">= " + checklist.getMinFreeSlots(),
				sat
			));
		}

		if (checklist.isCheckRangedAmmo())
		{
			if (!snapshot.isLoggedIn())
			{
				conditions.add(new ConditionCheck("Ammo Slot", "Logged out", "Equipped", false));
			}
			else if (!UnchargedItemDetector.needsAmmoSlot(snapshot.getEquippedWeaponId()))
			{
				conditions.add(new ConditionCheck("Ammo Slot", "Self-contained", "OK", true));
			}
			else
			{
				boolean sat = snapshot.getEquippedAmmoId() > 0;
				conditions.add(new ConditionCheck(
					"Ammo Slot",
					sat ? "Equipped" : "Empty",
					"Arrows / Bolts",
					sat
				));
			}
		}

		if (snapshot.isLoggedIn())
		{
			for (String warning : UnchargedItemDetector.detectCarriedWarnings(checklist, snapshot))
			{
				conditions.add(new ConditionCheck("Charge Warning", warning, "Recharge / Refill", false));
			}
		}

		if (checklist.getReminders() != null)
		{
			for (String reminder : checklist.getReminders())
			{
				if (reminder == null || reminder.trim().isEmpty())
				{
					continue;
				}
				String clean = reminder.trim();
				boolean isChecked = checkedReminders != null && checkedReminders.contains(clean);
				reminderChecks.add(new ReminderCheck(clean, isChecked));
			}
		}

		int condTotal = conditions.size();
		int condSat = 0;
		for (ConditionCheck cond : conditions)
		{
			if (cond.isSatisfied())
			{
				condSat++;
			}
		}

		int remTotal = reminderChecks.size();
		int remChecked = 0;
		for (ReminderCheck rem : reminderChecks)
		{
			if (rem.isChecked())
			{
				remChecked++;
			}
		}

		boolean ready = snapshot.isLoggedIn() && reqSat == reqTotal && condSat == condTotal && remChecked == remTotal;
		return new ChecklistEvaluation(
			checklist,
			snapshot.isLoggedIn(),
			ready,
			reqSat,
			reqTotal,
			condSat,
			condTotal,
			remChecked,
			remTotal,
			Collections.unmodifiableList(itemEvals),
			Collections.unmodifiableList(conditions),
			Collections.unmodifiableList(reminderChecks),
			Collections.unmodifiableMap(bankHighlights)
		);
	}

	private static int displayOrderRank(ItemEvaluation eval)
	{
		switch (eval.getStatus())
		{
			case MISSING:
				return 0;
			case PARTIAL:
				return 1;
			case OPTIONAL_MISSING:
				return eval.isRecommendedFromBank() ? 2 : 3;
			case SATISFIED:
			default:
				return 4;
		}
	}

	private static int bestCarriedId(ChecklistItem item, ItemGroup group, PlayerLoadoutSnapshot snapshot)
	{
		ItemSlotScope scope = item.getScope() != null ? item.getScope() : ItemSlotScope.ANY;
		int best = -1;
		if (scope == ItemSlotScope.ANY || scope == ItemSlotScope.EQUIPMENT)
		{
			best = group.bestAnyInPool(snapshot.getEquipmentCounts());
		}
		if (best <= 0 && (scope == ItemSlotScope.ANY || scope == ItemSlotScope.INVENTORY))
		{
			best = group.bestAnyInPool(snapshot.getInventoryCounts());
		}
		return best;
	}

	private static int countUsableInBank(ItemGroup group, PlayerLoadoutSnapshot snapshot)
	{
		Map<Integer, Integer> bank = snapshot.getBankCounts();
		if (bank == null || bank.isEmpty())
		{
			return 0;
		}
		int sum = 0;
		for (ItemGroup.ItemOption opt : group.getOptions())
		{
			if (opt.isUsableBy(snapshot))
			{
				sum += bank.getOrDefault(opt.getItemId(), 0);
			}
		}
		return sum;
	}

	private static CountResult countMatching(ChecklistItem item, PlayerLoadoutSnapshot snapshot)
	{
		ItemSlotScope scope = item.getScope() != null ? item.getScope() : ItemSlotScope.ANY;
		int total = 0;
		boolean unlimited = false;

		if (scope == ItemSlotScope.ANY || scope == ItemSlotScope.INVENTORY)
		{
			CountResult inv = countInMap(item, snapshot.getInventoryCounts());
			total += inv.count;
			unlimited |= inv.unlimitedSatisfied;
		}
		if (scope == ItemSlotScope.ANY || scope == ItemSlotScope.EQUIPMENT)
		{
			CountResult worn = countInMap(item, snapshot.getEquipmentCounts());
			total += worn.count;
			unlimited |= worn.unlimitedSatisfied;
		}
		if (item.isCheckRunePouch())
		{
			CountResult pouch = countInMap(item, snapshot.getRunePouchCounts());
			total += pouch.count;
			unlimited |= pouch.unlimitedSatisfied;
		}

		return new CountResult(total, unlimited);
	}

	private static CountResult countInMap(ChecklistItem item, Map<Integer, Integer> counts)
	{
		if (counts == null || counts.isEmpty())
		{
			return new CountResult(0, false);
		}
		ItemGroup group = item.resolveGroup();
		if (group != null)
		{
			int sum = 0;
			boolean unlimited = false;
			for (int id : group.getItemIds())
			{
				int qty = counts.getOrDefault(id, 0);
				if (qty > 0)
				{
					sum += qty;
					if (group.satisfiesFullQuantity(id))
					{
						unlimited = true;
					}
				}
			}
			return new CountResult(sum, unlimited);
		}

		int id = item.getItemId();
		if (id <= 0)
		{
			return new CountResult(0, false);
		}
		return new CountResult(counts.getOrDefault(id, 0), false);
	}

	@Value
	private static class CountResult
	{
		int count;
		boolean unlimitedSatisfied;
	}
}

package com.tripchecklist.logic;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.tripchecklist.data.ChecklistCategory;
import com.tripchecklist.data.ChecklistItem;
import com.tripchecklist.data.ItemGroup;
import com.tripchecklist.data.ItemSlotScope;
import com.tripchecklist.data.SpellbookType;
import com.tripchecklist.data.TripChecklist;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

public final class ChecklistSerializer
{
	private final Gson compactGson;
	private final Gson prettyGson;

	public ChecklistSerializer(Gson injectedGson)
	{
		this.compactGson = injectedGson;
		this.prettyGson = injectedGson.newBuilder().setPrettyPrinting().create();
	}

	public String serializeCustomList(List<TripChecklist> checklists)
	{
		TripChecklist[] array = checklists != null
			? checklists.toArray(new TripChecklist[0])
			: new TripChecklist[0];
		return compactGson.toJson(array, TripChecklist[].class);
	}

	public List<TripChecklist> deserializeCustomList(String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return new ArrayList<>();
		}
		try
		{
			TripChecklist[] parsed = compactGson.fromJson(json, TripChecklist[].class);
			if (parsed == null)
			{
				return new ArrayList<>();
			}
			List<TripChecklist> clean = new ArrayList<>(parsed.length);
			for (TripChecklist checklist : parsed)
			{
				TripChecklist normalized = normalizeImported(checklist, false);
				if (normalized != null)
				{
					clean.add(normalized);
				}
			}
			return clean;
		}
		catch (JsonParseException ex)
		{
			return new ArrayList<>();
		}
	}

	public String exportSingleJson(TripChecklist checklist)
	{
		TripChecklist exportCopy = checklist.copyAsCustom(checklist.getId(), checklist.getName());
		return prettyGson.toJson(exportCopy);
	}

	public TripChecklist importSingleJson(String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			throw new IllegalArgumentException("JSON input is empty.");
		}
		TripChecklist parsed;
		try
		{
			parsed = compactGson.fromJson(json.trim(), TripChecklist.class);
		}
		catch (JsonParseException ex)
		{
			throw new IllegalArgumentException("Invalid JSON format: " + ex.getMessage(), ex);
		}
		TripChecklist normalized = normalizeImported(parsed, true);
		if (normalized == null)
		{
			throw new IllegalArgumentException("JSON does not describe a valid Trip Checklist.");
		}
		return normalized;
	}

	private static TripChecklist normalizeImported(TripChecklist raw, boolean forceNewId)
	{
		if (raw == null || raw.getName() == null || raw.getName().trim().isEmpty())
		{
			return null;
		}
		String id = (!forceNewId && raw.getId() != null && !raw.getId().trim().isEmpty() && !raw.getId().startsWith("preset-"))
			? raw.getId().trim()
			: "custom-" + UUID.randomUUID().toString().substring(0, 8);

		List<ChecklistItem> cleanItems = new ArrayList<>();
		if (raw.getItems() != null)
		{
			for (ChecklistItem item : raw.getItems())
			{
				if (item == null)
				{
					continue;
				}
				ItemGroup group = item.resolveGroup();
				if (group == null && item.getItemId() <= 0)
				{
					continue;
				}
				String label = item.getLabel() != null && !item.getLabel().trim().isEmpty()
					? item.getLabel().trim()
					: (group != null ? group.getDisplayName() : ("Item #" + item.getItemId()));
				cleanItems.add(ChecklistItem.builder()
					.label(label)
					.itemId(item.getItemId() > 0 ? item.getItemId() : (group != null ? group.getIconItemId() : -1))
					.groupId(group != null ? group.name() : null)
					.quantity(Math.max(1, item.getQuantity()))
					.scope(item.getScope() != null ? item.getScope() : ItemSlotScope.ANY)
					.optional(item.isOptional())
					.checkRunePouch(item.isCheckRunePouch())
					.build());
			}
		}

		List<String> cleanReminders = new ArrayList<>();
		if (raw.getReminders() != null)
		{
			for (String r : raw.getReminders())
			{
				if (r != null && !r.trim().isEmpty())
				{
					cleanReminders.add(r.trim());
				}
			}
		}

		return TripChecklist.builder()
			.id(id)
			.name(raw.getName().trim())
			.category(raw.getCategory() != null ? raw.getCategory() : ChecklistCategory.CUSTOM)
			.builtIn(false)
			.requiredSpellbook(raw.getRequiredSpellbook() != null ? raw.getRequiredSpellbook() : SpellbookType.ANY)
			.minPrayerPercent(clampPercent(raw.getMinPrayerPercent()))
			.minRunEnergy(clampPercent(raw.getMinRunEnergy()))
			.minSpecPercent(clampPercent(raw.getMinSpecPercent()))
			.minFreeSlots(Math.max(0, Math.min(28, raw.getMinFreeSlots())))
			.checkRangedAmmo(raw.isCheckRangedAmmo())
			.notes(raw.getNotes() != null ? raw.getNotes().trim() : "")
			.items(cleanItems)
			.reminders(cleanReminders)
			.build();
	}

	private static int clampPercent(int value)
	{
		return Math.max(0, Math.min(100, value));
	}
}

package com.tripchecklist.logic;

import com.tripchecklist.data.ChecklistCategory;
import com.tripchecklist.data.ChecklistItem;
import com.tripchecklist.data.ItemGroup;
import com.tripchecklist.data.ItemSlotScope;
import com.tripchecklist.data.PlayerLoadoutSnapshot;
import com.tripchecklist.data.SpellbookType;
import com.tripchecklist.data.TripChecklist;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.function.IntFunction;

public final class LoadoutCapture
{
	private LoadoutCapture()
	{
	}

	public static TripChecklist capture(
		String name,
		ChecklistCategory category,
		PlayerLoadoutSnapshot snapshot,
		boolean collapseSmartGroups,
		IntFunction<String> itemNameResolver)
	{
		String cleanName = name != null && !name.trim().isEmpty() ? name.trim() : "Captured Loadout";
		ChecklistCategory cleanCategory = category != null ? category : ChecklistCategory.CUSTOM;
		String id = "custom-" + UUID.randomUUID().toString().substring(0, 8);

		List<ChecklistItem> capturedItems = new ArrayList<>();
		appendContainerItems(capturedItems, snapshot.getEquipmentCounts(), ItemSlotScope.EQUIPMENT, collapseSmartGroups, itemNameResolver);
		appendContainerItems(capturedItems, snapshot.getInventoryCounts(), ItemSlotScope.INVENTORY, collapseSmartGroups, itemNameResolver);

		// Include carried Rune Pouch runes so switching setups preserves pouch contents too.
		if (snapshot.hasRunePouchCarried() && !snapshot.getRunePouchCounts().isEmpty())
		{
			for (Map.Entry<Integer, Integer> entry : snapshot.getRunePouchCounts().entrySet())
			{
				int runeId = entry.getKey();
				int qty = entry.getValue();
				if (runeId <= 0 || qty <= 0)
				{
					continue;
				}
				String runeName = resolveName(runeId, itemNameResolver);
				ChecklistItem existing = findExactInventoryRune(capturedItems, runeId);
				if (existing != null)
				{
					existing.setQuantity(existing.getQuantity() + qty);
					existing.setCheckRunePouch(true);
				}
				else
				{
					capturedItems.add(ChecklistItem.rune(runeName, runeId, qty, false));
				}
			}
		}

		SpellbookType book = snapshot.isLoggedIn() && snapshot.getActiveSpellbook() != null
			? snapshot.getActiveSpellbook()
			: SpellbookType.ANY;

		return TripChecklist.builder()
			.id(id)
			.name(cleanName)
			.category(cleanCategory)
			.builtIn(false)
			.requiredSpellbook(book)
			.notes("Captured from worn gear, inventory, and active spellbook.")
			.items(capturedItems)
			.build();
	}

	private static void appendContainerItems(
		List<ChecklistItem> target,
		Map<Integer, Integer> counts,
		ItemSlotScope scope,
		boolean collapseSmartGroups,
		IntFunction<String> itemNameResolver)
	{
		if (counts == null || counts.isEmpty())
		{
			return;
		}
		Map<ItemGroup, Integer> groupedQuantities = new LinkedHashMap<>();
		for (Map.Entry<Integer, Integer> entry : counts.entrySet())
		{
			int itemId = entry.getKey();
			int qty = entry.getValue();
			if (itemId <= 0 || qty <= 0)
			{
				continue;
			}
			ItemGroup detected = collapseSmartGroups ? ItemGroup.detectForItemId(itemId) : null;
			if (detected != null)
			{
				groupedQuantities.merge(detected, qty, Integer::sum);
			}
			else
			{
				target.add(ChecklistItem.exact(resolveName(itemId, itemNameResolver), itemId, qty, scope, false));
			}
		}
		for (Map.Entry<ItemGroup, Integer> entry : groupedQuantities.entrySet())
		{
			ItemGroup group = entry.getKey();
			target.add(ChecklistItem.group(group.getDisplayName(), group, entry.getValue(), scope, false));
		}
	}

	private static ChecklistItem findExactInventoryRune(List<ChecklistItem> items, int runeId)
	{
		for (ChecklistItem item : items)
		{
			if (item.getGroupId() == null && item.getItemId() == runeId && item.getScope() == ItemSlotScope.INVENTORY)
			{
				return item;
			}
		}
		return null;
	}

	private static String resolveName(int itemId, IntFunction<String> resolver)
	{
		if (resolver != null)
		{
			String resolved = resolver.apply(itemId);
			if (resolved != null && !resolved.trim().isEmpty())
			{
				return resolved.trim();
			}
		}
		return "Item #" + itemId;
	}
}

package com.tripchecklist.logic;

import com.tripchecklist.data.ChecklistItem;
import com.tripchecklist.data.ItemGroup;
import com.tripchecklist.data.PlayerLoadoutSnapshot;
import com.tripchecklist.data.TripChecklist;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.ItemID;

public final class UnchargedItemDetector
{
	private static final Map<Integer, String> ALWAYS_WARN_ITEMS;
	private static final Map<Integer, ItemGroup> TELEPORT_JEWELRY_ZERO_CHARGE;
	private static final Set<Integer> SELF_CONTAINED_RANGED_WEAPONS;

	static
	{
		Map<Integer, String> always = new LinkedHashMap<>();
		always.put(ItemID.ECTOPHIAL_EMPTY, "Ectophial is empty");
		always.put(ItemID.BOTTOMLESS_COMPOST_BUCKET, "Bottomless compost bucket is empty");
		always.put(ItemID.XERIC_TALISMAN_EMPTY, "Xeric's talisman is uncharged");
		always.put(ItemID.NECKLACE_OF_DIGSITE, "Digsite pendant has 0 charges");
		always.put(ItemID.DRAGONFIRE_SHIELD_UNCHARGED, "Dragonfire shield is uncharged");
		always.put(ItemID.TOXIC_BLOWPIPE, "Toxic blowpipe is unloaded");
		always.put(ItemID.SERPENTINE_HELM, "Serpentine helm is uncharged");
		always.put(ItemID.SERPENTINE_HELM_CYAN, "Tanzanite helm is uncharged");
		always.put(ItemID.SERPENTINE_HELM_RED, "Magma helm is uncharged");
		always.put(ItemID.BOW_OF_FAERDHINEN_INACTIVE, "Bow of faerdhinen is inactive");
		always.put(ItemID.ARCLIGHT_INACTIVE, "Arclight is uncharged");
		always.put(ItemID.CRYSTAL_AXE_INACTIVE, "Crystal axe is inactive");
		always.put(ItemID.CRYSTAL_AXE_2H_INACTIVE, "Crystal 2h axe is inactive");
		always.put(ItemID.CRYSTAL_PICKAXE_INACTIVE, "Crystal pickaxe is inactive");
		always.put(ItemID.CRYSTAL_HARPOON_INACTIVE, "Crystal harpoon is inactive");
		always.put(ItemID.INFERNAL_AXE_EMPTY, "Infernal axe is uncharged");
		always.put(ItemID.INFERNAL_PICKAXE_EMPTY, "Infernal pickaxe is uncharged");
		always.put(ItemID.INFERNAL_HARPOON_EMPTY, "Infernal harpoon is uncharged");
		always.put(ItemID.RING_OF_ENDURANCE_UNCHARGED, "Ring of endurance is uncharged");
		always.put(ItemID.RING_OF_ENDURANCE_NOCHARGES, "Ring of endurance has 0 charges");
		always.put(ItemID.RING_OF_SHADOWS_UNCHARGED, "Ring of shadows is uncharged");
		ALWAYS_WARN_ITEMS = Collections.unmodifiableMap(always);

		// Uncharged stat jewelry only warns when the active checklist expects that teleport group.
		Map<Integer, ItemGroup> teleZero = new HashMap<>();
		teleZero.put(ItemID.AMULET_OF_GLORY, ItemGroup.AMULET_OF_GLORY);
		teleZero.put(ItemID.JEWL_NECKLACE_OF_SKILLS, ItemGroup.SKILLS_NECKLACE);
		teleZero.put(ItemID.JEWL_BRACELET_OF_COMBAT, ItemGroup.COMBAT_BRACELET);
		teleZero.put(ItemID.RING_OF_WEALTH, ItemGroup.RING_OF_WEALTH);
		TELEPORT_JEWELRY_ZERO_CHARGE = Collections.unmodifiableMap(teleZero);

		Set<Integer> selfContained = new HashSet<>();
		selfContained.add(ItemID.TOXIC_BLOWPIPE_LOADED);
		selfContained.add(ItemID.TOXIC_BLOWPIPE_LOADED_ORNAMENT);
		selfContained.add(ItemID.TOXIC_BLOWPIPE);
		selfContained.add(ItemID.BOW_OF_FAERDHINEN);
		selfContained.add(ItemID.BOW_OF_FAERDHINEN_INFINITE);
		selfContained.add(ItemID.BOW_OF_FAERDHINEN_INFINITE_ITHELL);
		selfContained.add(ItemID.BOW_OF_FAERDHINEN_INFINITE_IORWERTH);
		selfContained.add(ItemID.BOW_OF_FAERDHINEN_INFINITE_TRAHAEARN);
		selfContained.add(ItemID.BOW_OF_FAERDHINEN_INFINITE_CADARN);
		selfContained.add(ItemID.BOW_OF_FAERDHINEN_INFINITE_CRWYS);
		selfContained.add(ItemID.BOW_OF_FAERDHINEN_INFINITE_MEILYR);
		selfContained.add(ItemID.BOW_OF_FAERDHINEN_INFINITE_AMLODD);
		selfContained.add(ItemID.CRYSTAL_BOW);
		SELF_CONTAINED_RANGED_WEAPONS = Collections.unmodifiableSet(selfContained);
	}

	private UnchargedItemDetector()
	{
	}

	public static List<String> detectCarriedWarnings(TripChecklist checklist, PlayerLoadoutSnapshot snapshot)
	{
		if (snapshot == null || !snapshot.isLoggedIn())
		{
			return Collections.emptyList();
		}

		Set<Integer> carriedIds = new HashSet<>();
		carriedIds.addAll(snapshot.getInventoryCounts().keySet());
		carriedIds.addAll(snapshot.getEquipmentCounts().keySet());

		List<String> warnings = new ArrayList<>();
		for (Map.Entry<Integer, String> entry : ALWAYS_WARN_ITEMS.entrySet())
		{
			if (carriedIds.contains(entry.getKey()))
			{
				warnings.add(entry.getValue());
			}
		}

		if (checklist != null && checklist.getItems() != null)
		{
			Set<ItemGroup> expectedGroups = new HashSet<>();
			for (ChecklistItem item : checklist.getItems())
			{
				ItemGroup g = item.resolveGroup();
				if (g != null)
				{
					expectedGroups.add(g);
				}
			}
			for (Map.Entry<Integer, ItemGroup> entry : TELEPORT_JEWELRY_ZERO_CHARGE.entrySet())
			{
				if (carriedIds.contains(entry.getKey()) && expectedGroups.contains(entry.getValue()))
				{
					warnings.add(entry.getValue().getDisplayName() + " has 0 charges");
				}
			}
		}

		return warnings;
	}

	public static boolean needsAmmoSlot(int equippedWeaponId)
	{
		if (equippedWeaponId <= 0)
		{
			return true;
		}
		return !SELF_CONTAINED_RANGED_WEAPONS.contains(equippedWeaponId);
	}
}

package com.tripchecklist.overlay;

import com.tripchecklist.TripChecklistConfig;
import com.tripchecklist.TripChecklistPlugin;
import com.tripchecklist.logic.ChecklistEvaluator.BankHighlightHint;
import com.tripchecklist.logic.ChecklistEvaluator.ChecklistEvaluation;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

@Singleton
public class BankChecklistOverlay extends WidgetItemOverlay
{
	private static final Stroke BORDER_STROKE = new BasicStroke(1.5f);
	private static final Color SHADOW_COLOR = new Color(0, 0, 0, 210);

	private final TripChecklistPlugin plugin;
	private final TripChecklistConfig config;
	private final ItemManager itemManager;

	private Color cachedReqBase;
	private Color cachedReqFill;
	private Color cachedOptBase;
	private Color cachedOptFill;

	@Inject
	public BankChecklistOverlay(
		TripChecklistPlugin plugin,
		TripChecklistConfig config,
		ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		showOnBank();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.highlightBankItems() || itemId <= 0 || widgetItem.getQuantity() <= 0)
		{
			return;
		}
		ChecklistEvaluation eval = plugin.getActiveEvaluation();
		if (eval == null || !eval.isLoggedIn() || eval.getBankHighlightsByItemId().isEmpty())
		{
			return;
		}

		int canonicalId = itemManager.canonicalize(itemId);
		BankHighlightHint hint = eval.getBankHighlight(canonicalId);
		if (hint == null)
		{
			return;
		}
		if (hint.isOptional() && !config.highlightOptionalBankItems())
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds == null || bounds.width <= 2 || bounds.height <= 2)
		{
			return;
		}

		Color borderColor = hint.isOptional() ? config.bankOptionalColor() : config.bankRequiredColor();
		Color fillColor = hint.isOptional() ? getOptionalFill(borderColor) : getRequiredFill(borderColor);

		Stroke prevStroke = graphics.getStroke();
		graphics.setColor(fillColor);
		graphics.fillRoundRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1, 4, 4);

		graphics.setStroke(BORDER_STROKE);
		graphics.setColor(borderColor);
		graphics.drawRoundRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1, 4, 4);
		graphics.setStroke(prevStroke);

		if (config.showBankMissingQuantity() && hint.getMissingCount() > 0)
		{
			String badge = "-" + formatCompactQty(hint.getMissingCount());
			Font prevFont = graphics.getFont();
			Font smallFont = FontManager.getRunescapeSmallFont();
			graphics.setFont(smallFont);
			FontMetrics fm = graphics.getFontMetrics();
			int textW = fm.stringWidth(badge);
			int textX = bounds.x + bounds.width - textW - 2;
			int textY = bounds.y + bounds.height - 2;

			graphics.setColor(SHADOW_COLOR);
			graphics.drawString(badge, textX + 1, textY + 1);
			graphics.setColor(borderColor);
			graphics.drawString(badge, textX, textY);
			graphics.setFont(prevFont);
		}
	}

	private Color getRequiredFill(Color base)
	{
		if (!base.equals(cachedReqBase))
		{
			cachedReqBase = base;
			cachedReqFill = new Color(base.getRed(), base.getGreen(), base.getBlue(), 42);
		}
		return cachedReqFill;
	}

	private Color getOptionalFill(Color base)
	{
		if (!base.equals(cachedOptBase))
		{
			cachedOptBase = base;
			cachedOptFill = new Color(base.getRed(), base.getGreen(), base.getBlue(), 34);
		}
		return cachedOptFill;
	}

	private static String formatCompactQty(int count)
	{
		if (count >= 10000)
		{
			return (count / 1000) + "k";
		}
		return Integer.toString(count);
	}
}

package com.tripchecklist.overlay;

import com.tripchecklist.TripChecklistConfig;
import com.tripchecklist.TripChecklistPlugin;
import com.tripchecklist.data.PlayerLoadoutSnapshot;
import com.tripchecklist.logic.ChecklistEvaluator.ChecklistEvaluation;
import com.tripchecklist.logic.ChecklistEvaluator.ConditionCheck;
import com.tripchecklist.logic.ChecklistEvaluator.ItemEvaluation;
import com.tripchecklist.logic.ChecklistEvaluator.ItemStatus;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

@Singleton
public class TripHudOverlay extends OverlayPanel
{
	private static final Color READY_GREEN = new Color(56, 214, 134);
	private static final Color WARN_GOLD = new Color(245, 194, 66);
	private static final Color MISSING_RED = new Color(239, 98, 98);
	private static final Color BANK_HINT_BLUE = new Color(120, 196, 255);
	private static final Color MUTED_TEXT = new Color(175, 185, 195);

	private final TripChecklistPlugin plugin;
	private final TripChecklistConfig config;

	@Inject
	public TripHudOverlay(TripChecklistPlugin plugin, TripChecklistConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		addMenuEntry(MenuAction.RUNELITE_OVERLAY, "Deselect", "Trip Checklist", e -> plugin.clearActiveChecklist());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showHudOverlay())
		{
			return null;
		}
		ChecklistEvaluation eval = plugin.getActiveEvaluation();
		PlayerLoadoutSnapshot snapshot = plugin.getLatestSnapshot();
		if (eval == null || snapshot == null || !snapshot.isLoggedIn())
		{
			return null;
		}
		if (config.hudOnlyAtBank() && !snapshot.isBankOpen())
		{
			return null;
		}
		if (config.autoHideHudWhenReady() && eval.isReady())
		{
			return null;
		}

		FontMetrics fm = graphics.getFontMetrics();
		int maxWidth = Math.max(175, fm.stringWidth(eval.getChecklist().getName()) + 24);

		panelComponent.getChildren().add(TitleComponent.builder()
			.text(eval.getChecklist().getName())
			.color(eval.isReady() ? READY_GREEN : WARN_GOLD)
			.build());

		String statusRight = eval.isReady()
			? "READY"
			: ("Missing " + eval.getMissingRequiredTotal());
		maxWidth = addRow(fm, maxWidth, "Status", statusRight, Color.WHITE, eval.isReady() ? READY_GREEN : MISSING_RED);

		String itemsRight = eval.getRequiredSatisfied() + " / " + eval.getRequiredTotal();
		maxWidth = addRow(fm, maxWidth, "Required", itemsRight, MUTED_TEXT, eval.getRequiredSatisfied() == eval.getRequiredTotal() ? READY_GREEN : WARN_GOLD);

		if (eval.isReady()
			&& snapshot.isBankOpen()
			&& config.onReadyBehavior() == TripChecklistConfig.OnReadyBehavior.AUTO_CLOSE_ON_BANK_CLOSE)
		{
			maxWidth = addRow(fm, maxWidth, "Close bank to finish", "", MUTED_TEXT, MUTED_TEXT);
		}

		for (ConditionCheck cond : eval.getConditions())
		{
			if (!cond.isSatisfied())
			{
				String right = "Charge Warning".equals(cond.getLabel())
					? truncate(cond.getCurrentValue(), 24)
					: (cond.getCurrentValue() + " (" + cond.getExpectedValue() + ")");
				maxWidth = addRow(fm, maxWidth, cond.getLabel(), right, WARN_GOLD, MISSING_RED);
			}
		}

		if (eval.getRemindersTotal() > 0 && eval.getRemindersChecked() < eval.getRemindersTotal())
		{
			String remRight = eval.getRemindersChecked() + " / " + eval.getRemindersTotal();
			maxWidth = addRow(fm, maxWidth, "Reminders", remRight, WARN_GOLD, MISSING_RED);
		}

		int shown = 0;
		int hiddenMissing = 0;
		int limit = config.hudMaxMissingRows();
		for (ItemEvaluation itemEval : eval.getItemsSortedMissingFirst())
		{
			if (itemEval.getItem().isOptional() || itemEval.isSatisfied())
			{
				continue;
			}
			if (shown < limit)
			{
				String displayName = itemEval.getItem().getLabel();
				if (itemEval.getRequiredCount() == 1 && itemEval.getItem().resolveGroup() != null)
				{
					String resolved = plugin.getCachedItemName(itemEval.getRecommendedItemId());
					if (resolved != null && !resolved.isEmpty())
					{
						displayName = resolved;
					}
				}
				String left = truncate(displayName, 22);
				int missing = itemEval.getMissingCount();
				boolean hasInBank = !snapshot.isUltimateIronman() && itemEval.getInBankCount() > 0;
				String right = "-" + missing + (hasInBank ? " (bank)" : "");
				Color rightColor = hasInBank
					? BANK_HINT_BLUE
					: (itemEval.getStatus() == ItemStatus.PARTIAL ? WARN_GOLD : MISSING_RED);
				maxWidth = addRow(fm, maxWidth, left, right, Color.WHITE, rightColor);
				shown++;
			}
			else
			{
				hiddenMissing++;
			}
		}

		if (hiddenMissing > 0)
		{
			maxWidth = addRow(fm, maxWidth, "... and " + hiddenMissing + " more", "", MUTED_TEXT, MUTED_TEXT);
		}

		panelComponent.setPreferredSize(new Dimension(Math.min(maxWidth, 320), 0));
		return super.render(graphics);
	}

	private int addRow(FontMetrics fm, int currentMaxWidth, String left, String right, Color leftColor, Color rightColor)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(left)
			.leftColor(leftColor)
			.right(right)
			.rightColor(rightColor)
			.build());
		int needed = fm.stringWidth(left) + fm.stringWidth(right) + 32;
		return Math.max(currentMaxWidth, needed);
	}

	private static String truncate(String text, int maxLen)
	{
		if (text == null || text.length() <= maxLen)
		{
			return text != null ? text : "";
		}
		return text.substring(0, maxLen - 1) + "\u2026";
	}
}

