	private void populateHeaderFields()
	{
		nameField.setText(editingSource.getName());
		categoryCombo.setSelectedItem(editingSource.getCategory() != null ? editingSource.getCategory() : ChecklistCategory.CUSTOM);
		spellbookCombo.setSelectedItem(editingSource.getRequiredSpellbook() != null ? editingSource.getRequiredSpellbook() : SpellbookType.ANY);
		prayerSpinner.setValue(editingSource.getMinPrayerPercent());
		runSpinner.setValue(editingSource.getMinRunEnergy());
		specSpinner.setValue(editingSource.getMinSpecPercent());
		freeSlotsSpinner.setValue(editingSource.getMinFreeSlots());
		checkRangedAmmo = editingSource.isCheckRangedAmmo();
		if (ammoToggleBtn != null)
		{
			styleTogglePill(ammoToggleBtn, checkRangedAmmo, ACCENT_GOLD);
		}
		remindersField.setText(editingSource.getReminders() != null ? String.join("; ", editingSource.getReminders()) : "");
		notesField.setText(editingSource.getNotes() != null ? editingSource.getNotes() : "");
	}

	private void rebuildItemsList()
	{
		itemsListPanel.removeAll();
		if (workingItems.isEmpty())
		{
			JLabel empty = mutedLabel("No items yet. Add a smart group or search for items above.");
			empty.setBorder(new EmptyBorder(12, 8, 12, 8));
			itemsListPanel.add(empty);
		}
		else
		{
			for (int i = 0; i < workingItems.size(); i++)
			{
				itemsListPanel.add(createItemRow(i, workingItems.get(i)));
				itemsListPanel.add(Box.createVerticalStrut(4));
			}
		}
		itemsListPanel.revalidate();
		itemsListPanel.repaint();
	}

	private JPanel createItemRow(int index, ChecklistItem item)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(SURFACE_CARD);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(BORDER_SUBTLE),
			new EmptyBorder(5, 8, 5, 8)
		));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 44));

		StringBuilder meta = new StringBuilder();
		meta.append(item.getScope() != null ? item.getScope().getDisplayName() : "Any");
		if (item.resolveGroup() != null)
		{
			meta.append(" | Group");
		}
		if (item.isCheckRunePouch())
		{
			meta.append(" | Pouch");
		}
		if (item.isOptional())
		{
			meta.append(" | Optional");
		}

		JPanel textCol = new JPanel(new GridLayout(2, 1));
		textCol.setOpaque(false);
		JLabel nameLbl = new JLabel(item.getLabel() + " (x" + item.getQuantity() + ")");
		nameLbl.setForeground(Color.WHITE);
		nameLbl.setFont(nameLbl.getFont().deriveFont(Font.BOLD, 11.5f));
		JLabel metaLbl = new JLabel(meta.toString());
		metaLbl.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		metaLbl.setFont(metaLbl.getFont().deriveFont(10f));
		textCol.add(nameLbl);
		textCol.add(metaLbl);
		row.add(textCol, BorderLayout.CENTER);

		JPanel controls = new JPanel(new FlowLayout(FlowLayout.RIGHT, 3, 0));
		controls.setOpaque(false);

		JButton minusBtn = compactButton("-", ColorScheme.MEDIUM_GRAY_COLOR);
		minusBtn.addActionListener(e ->
		{
			if (item.getQuantity() > 1)
			{
				item.setQuantity(item.getQuantity() - 1);
				rebuildItemsList();
			}
		});

		JButton plusBtn = compactButton("+", ColorScheme.MEDIUM_GRAY_COLOR);
		plusBtn.addActionListener(e ->
		{
			item.setQuantity(item.getQuantity() + 1);
			rebuildItemsList();
		});

		JButton optBtn = compactButton(item.isOptional() ? "Opt" : "Req",
			item.isOptional() ? ACCENT_GOLD : ColorScheme.MEDIUM_GRAY_COLOR);
		optBtn.addActionListener(e ->
		{
			item.setOptional(!item.isOptional());
			rebuildItemsList();
		});

		JButton removeBtn = compactButton("X", DANGER_RED);
		removeBtn.addActionListener(e ->
		{
			workingItems.remove(index);
			rebuildItemsList();
		});

		controls.add(minusBtn);
		controls.add(plusBtn);
		controls.add(optBtn);
		controls.add(removeBtn);
		row.add(controls, BorderLayout.EAST);

		return row;
	}

	private void saveAndClose()
	{
		String name = nameField.getText().trim();
		if (name.isEmpty())
		{
			JOptionPane.showMessageDialog(this, "Checklist name cannot be empty.", "Invalid Name", JOptionPane.WARNING_MESSAGE);
			return;
		}
		List<String> parsedReminders = new ArrayList<>();
		String rawReminders = remindersField.getText().trim();
		if (!rawReminders.isEmpty())
		{
			for (String part : rawReminders.split(";"))
			{
				String trimmed = part.trim();
				if (!trimmed.isEmpty())
				{
					parsedReminders.add(trimmed);
				}
			}
		}

		TripChecklist saved = TripChecklist.builder()
			.id(editingSource.getId())
			.name(name)
			.category((ChecklistCategory) categoryCombo.getSelectedItem())
			.builtIn(false)
			.requiredSpellbook((SpellbookType) spellbookCombo.getSelectedItem())
			.minPrayerPercent((Integer) prayerSpinner.getValue())
			.minRunEnergy((Integer) runSpinner.getValue())
			.minSpecPercent((Integer) specSpinner.getValue())
			.minFreeSlots((Integer) freeSlotsSpinner.getValue())
			.checkRangedAmmo(checkRangedAmmo)
			.notes(notesField.getText().trim())
			.items(new ArrayList<>(workingItems))
			.reminders(parsedReminders)
			.build();
		onSave.accept(saved);
		dispose();
	}

	private static JPanel labeledSpinner(String label, JSpinner spinner)
	{
		JPanel p = new JPanel(new BorderLayout(4, 0));
		p.setOpaque(false);
		p.add(mutedLabel(label), BorderLayout.WEST);
		p.add(spinner, BorderLayout.CENTER);
		return p;
	}

	private static JLabel mutedLabel(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(label.getFont().deriveFont(11f));
		return label;
	}

	private static JButton flatButton(String text, Color bg)
	{
		JButton btn = new JButton(text);
		btn.setFocusPainted(false);
		btn.setBackground(bg);
		btn.setForeground(Color.WHITE);
		btn.setBorder(new EmptyBorder(5, 10, 5, 10));
		btn.setFont(btn.getFont().deriveFont(Font.BOLD, 11f));
		return btn;
	}

	private static JButton compactButton(String text, Color bg)
	{
		JButton btn = new JButton(text);
		btn.setFocusPainted(false);
		btn.setBackground(bg);
		btn.setForeground(Color.WHITE);
		btn.setBorder(new EmptyBorder(3, 6, 3, 6));
		btn.setFont(btn.getFont().deriveFont(Font.BOLD, 10f));
		return btn;
	}

	private static JButton createTogglePill(String text, boolean active)
	{
		JButton btn = new JButton(text);
		btn.setFocusPainted(false);
		btn.setFont(btn.getFont().deriveFont(Font.BOLD, 10.5f));
		styleTogglePill(btn, active, ACCENT_GOLD);
		return btn;
	}

	private static void styleTogglePill(JButton btn, boolean active, Color activeColor)
	{
		btn.setBackground(active ? activeColor : ColorScheme.MEDIUM_GRAY_COLOR);
		btn.setForeground(active ? Color.BLACK : Color.WHITE);
		btn.setBorder(new EmptyBorder(4, 8, 4, 8));
	}
}

