	private void addFilterPill(JPanel parent, String key, String label, @Nullable ChecklistCategory category)
	{
		JButton btn = flatButton(label, SURFACE_ELEVATED);
		btn.setFont(btn.getFont().deriveFont(Font.BOLD, 9.8f));
		btn.setBorder(new EmptyBorder(4, 2, 4, 2));
		btn.addActionListener(e ->
		{
			categoryFilter = category;
			persistCategoryFilter();
			refresh();
		});
		categoryButtons.put(key, btn);
		parent.add(btn);
	}

	public void refresh()
	{
		updateHeaderStatus();
		updateCategoryPillStyles();
		updateViewPillStyles();
		rebuildChecklistCombo();
		rebuildBody();
	}

	private void updateHeaderStatus()
	{
		PlayerLoadoutSnapshot snap = plugin.getLatestSnapshot();
		if (snap == null || !snap.isLoggedIn())
		{
			accountStatusLabel.setText("Logged out");
			accountStatusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			return;
		}
		StringBuilder sb = new StringBuilder();
		sb.append(snap.isMembersWorld() ? "P2P" : "F2P");
		String ironman = snap.getAccountTypeShortLabel();
		if (!ironman.isEmpty())
		{
			sb.append(" ").append(ironman);
		}
		sb.append(" | ").append(snap.getActiveSpellbook().getDisplayName());
		if (snap.isBankOpen())
		{
			sb.append(" | Bank");
		}
		accountStatusLabel.setText(sb.toString());
		accountStatusLabel.setForeground(snap.isBankOpen() ? BANK_BLUE : ColorScheme.LIGHT_GRAY_COLOR);
	}

	private void updateCategoryPillStyles()
	{
		String activeKey = categoryFilter == null ? "ALL" : categoryFilter.name();
		for (Map.Entry<String, JButton> entry : categoryButtons.entrySet())
		{
			boolean selected = activeKey.equals(entry.getKey());
			JButton btn = entry.getValue();
			btn.setBackground(selected ? PILL_ACTIVE : SURFACE_ELEVATED);
			btn.setForeground(selected ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
		}
	}

	private void updateViewPillStyles()
	{
		missingOnlyPill.setBackground(missingOnlyFilter ? WARN_GOLD : SURFACE_ELEVATED);
		missingOnlyPill.setForeground(missingOnlyFilter ? Color.BLACK : ColorScheme.LIGHT_GRAY_COLOR);

		boolean showOpt = config.showOptionalItemsInPanel();
		showOptionalPill.setBackground(showOpt ? PILL_ACTIVE : SURFACE_ELEVATED);
		showOptionalPill.setForeground(showOpt ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
	}

	private void rebuildChecklistCombo()
	{
		updatingCombo = true;
		try
		{
			checklistCombo.removeAllItems();
			checklistCombo.addItem(null);

			String activeId = plugin.getActiveChecklistId();
			TripChecklist toSelect = null;

			List<TripChecklist> all = plugin.getAllChecklists();
			for (TripChecklist c : all)
			{
				boolean matchesCategory = categoryFilter == null
					|| (categoryFilter == ChecklistCategory.CUSTOM ? !c.isBuiltIn() : c.getCategory() == categoryFilter);
				if (matchesCategory || (activeId != null && activeId.equals(c.getId())))
				{
					checklistCombo.addItem(c);
					if (activeId != null && activeId.equals(c.getId()))
					{
						toSelect = c;
					}
				}
			}
			checklistCombo.setSelectedItem(toSelect);
		}
		finally
		{
			updatingCombo = false;
		}
	}

	private void rebuildBody()
	{
		bodyPanel.removeAll();
		ChecklistEvaluation eval = plugin.getActiveEvaluation();
		if (eval == null)
		{
			bodyPanel.add(buildEmptyPickerCard());
		}
		else
		{
			bodyPanel.add(buildActiveSummaryCard(eval));
			bodyPanel.add(Box.createVerticalStrut(6));

			if (!eval.getConditions().isEmpty())
			{
				bodyPanel.add(buildConditionsCard(eval));
				bodyPanel.add(Box.createVerticalStrut(6));
			}

			if (!eval.getReminders().isEmpty())
			{
				bodyPanel.add(buildRemindersCard(eval));
				bodyPanel.add(Box.createVerticalStrut(6));
			}

			bodyPanel.add(buildItemsSection(eval));

			String notes = eval.getChecklist().getNotes();
			if (notes != null && !notes.trim().isEmpty())
			{
				bodyPanel.add(Box.createVerticalStrut(6));
				bodyPanel.add(buildNotesCard(notes.trim()));
			}
		}
		bodyPanel.revalidate();
		bodyPanel.repaint();
	}

	private JPanel buildEmptyPickerCard()
	{
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(SURFACE_CARD);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(BORDER_SUBTLE),
			new EmptyBorder(10, 10, 10, 10)
		));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel title = new JLabel("Select or Capture a Trip");
		title.setForeground(Color.WHITE);
		title.setFont(title.getFont().deriveFont(Font.BOLD, 12.5f));
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(title);
		card.add(Box.createVerticalStrut(5));

		JTextArea desc = wrappingText(
			"Pick a checklist below, star favorites to pin daily runs to the top, or click Capture to turn your current gear, inventory, rune pouch, and spellbook into a custom checklist.",
			ColorScheme.LIGHT_GRAY_COLOR,
			11f
		);
		card.add(desc);
		card.add(Box.createVerticalStrut(8));

		List<TripChecklist> visible = new ArrayList<>();
		for (TripChecklist c : plugin.getAllChecklists())
		{
			boolean matches = categoryFilter == null
				|| (categoryFilter == ChecklistCategory.CUSTOM ? !c.isBuiltIn() : c.getCategory() == categoryFilter);
			if (matches)
			{
				visible.add(c);
			}
		}

		if (visible.isEmpty())
		{
			card.add(wrappingText("No custom checklists saved yet. Click Capture or New to create one.", WARN_GOLD, 11f));
		}
		else
		{
			for (TripChecklist checklist : visible)
			{
				card.add(buildQuickPickRow(checklist));
				card.add(Box.createVerticalStrut(4));
			}
		}

		return card;
