	private JPanel buildActiveSummaryCard(ChecklistEvaluation eval)
	{
		TripChecklist checklist = eval.getChecklist();
		boolean ready = eval.isReady();
		Color accent = !eval.isLoggedIn() ? ColorScheme.LIGHT_GRAY_COLOR : (ready ? READY_GREEN : WARN_GOLD);
		Color bg = !eval.isLoggedIn() ? SURFACE_CARD : (ready ? READY_BG : WARN_BG);

		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(bg);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(accent),
			new EmptyBorder(8, 9, 8, 9)
		));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel topRow = new JPanel(new BorderLayout(5, 0));
		topRow.setOpaque(false);
		topRow.setAlignmentX(Component.LEFT_ALIGNMENT);

		topRow.add(createStarButton(checklist.getId()), BorderLayout.WEST);

		JLabel name = new JLabel(checklist.getName());
		name.setForeground(Color.WHITE);
		name.setFont(name.getFont().deriveFont(Font.BOLD, 12f));
		topRow.add(name, BorderLayout.CENTER);

		String badgeText = !eval.isLoggedIn()
			? "LOGGED OUT"
			: (ready ? "READY" : ("MISSING " + eval.getMissingRequiredTotal()));
		JLabel badge = new JLabel(badgeText);
		badge.setForeground(ready ? READY_GREEN : (eval.isLoggedIn() ? MISSING_RED : ColorScheme.LIGHT_GRAY_COLOR));
		badge.setFont(badge.getFont().deriveFont(Font.BOLD, 10.5f));
		topRow.add(badge, BorderLayout.EAST);
		card.add(topRow);
		card.add(Box.createVerticalStrut(5));

		int total = Math.max(1, eval.getRequiredTotal() + eval.getConditionsTotal() + eval.getRemindersTotal());
		int done = eval.getRequiredSatisfied() + eval.getConditionsSatisfied() + eval.getRemindersChecked();
		double ratio = eval.isLoggedIn() ? ((double) done / total) : 0.0;
		card.add(new ProgressStrip(ratio, ready ? READY_GREEN : WARN_GOLD));
		card.add(Box.createVerticalStrut(5));

		StringBuilder counts = new StringBuilder();
		counts.append("Req: ").append(eval.getRequiredSatisfied()).append("/").append(eval.getRequiredTotal());
		if (eval.getConditionsTotal() > 0)
		{
			counts.append(" | Checks: ").append(eval.getConditionsSatisfied()).append("/").append(eval.getConditionsTotal());
		}
		if (eval.getRemindersTotal() > 0)
		{
			counts.append(" | Rem: ").append(eval.getRemindersChecked()).append("/").append(eval.getRemindersTotal());
		}
		JLabel countsLbl = new JLabel(counts.toString());
		countsLbl.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		countsLbl.setFont(countsLbl.getFont().deriveFont(10.5f));
		countsLbl.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(countsLbl);
		card.add(Box.createVerticalStrut(7));

		if (ready)
		{
			JButton doneBtn = flatButton("Ready - Stop Tracking", READY_GREEN);
			doneBtn.setForeground(Color.BLACK);
			doneBtn.setAlignmentX(Component.LEFT_ALIGNMENT);
			doneBtn.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
			doneBtn.setToolTipText("Finish this checklist, clear HUD and bank highlights, and reset manual reminders for next time");
			doneBtn.addActionListener(e -> plugin.completeActiveChecklist());
			card.add(doneBtn);
			card.add(Box.createVerticalStrut(5));
		}

		int secondaryCols = ready
			? (checklist.isBuiltIn() ? 2 : 3)
			: (checklist.isBuiltIn() ? 3 : 4);
		JPanel actions = new JPanel(new GridLayout(1, secondaryCols, 4, 0));
		actions.setOpaque(false);
		actions.setAlignmentX(Component.LEFT_ALIGNMENT);
		actions.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));

		if (!ready)
		{
			JButton deselectBtn = flatButton("Deselect", SURFACE_ELEVATED);
			deselectBtn.addActionListener(e -> plugin.clearActiveChecklist());
			actions.add(deselectBtn);
		}

		if (checklist.isBuiltIn())
		{
			JButton customizeBtn = flatButton("Customize", PILL_ACTIVE);
			customizeBtn.setToolTipText("Duplicate this preset as an editable custom checklist");
			customizeBtn.addActionListener(e ->
			{
				TripChecklist copy = checklist.copyAsCustom(
					"custom-" + UUID.randomUUID().toString().substring(0, 8),
					checklist.getName() + " (Custom)"
				);
				openEditor(copy);
			});
			actions.add(customizeBtn);
		}
		else
		{
			JButton editBtn = flatButton("Edit", PILL_ACTIVE);
			editBtn.addActionListener(e -> openEditor(checklist));
			actions.add(editBtn);

			JButton delBtn = flatButton("Delete", new Color(150, 52, 56));
			delBtn.addActionListener(e ->
			{
				int confirm = JOptionPane.showConfirmDialog(
					this,
					"Delete custom checklist \"" + checklist.getName() + "\"?",
					"Delete Checklist",
					JOptionPane.YES_NO_OPTION
				);
				if (confirm == JOptionPane.YES_OPTION)
				{
					plugin.deleteCustomChecklist(checklist.getId());
				}
			});
			actions.add(delBtn);
		}

		JButton copyBtn = flatButton("Copy", SURFACE_ELEVATED);
		copyBtn.setToolTipText("Copy checklist JSON to clipboard");
		copyBtn.addActionListener(e -> copyJsonToClipboard(checklist));
		actions.add(copyBtn);

		card.add(actions);
		return card;
	}

	private JPanel buildConditionsCard(ChecklistEvaluation eval)
	{
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(SURFACE_CARD);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(BORDER_SUBTLE),
			new EmptyBorder(7, 8, 7, 8)
		));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel header = new JLabel("Pre-Trip Checks");
		header.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		header.setFont(header.getFont().deriveFont(Font.BOLD, 10.5f));
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.add(header);
		card.add(Box.createVerticalStrut(4));

		for (ConditionCheck cond : eval.getConditions())
		{
			JPanel row = new JPanel(new BorderLayout(6, 0));
			row.setOpaque(false);
			row.setAlignmentX(Component.LEFT_ALIGNMENT);

			boolean isChargeWarn = "Charge Warning".equals(cond.getLabel());
			JLabel left = new JLabel(
				isChargeWarn ? cond.getCurrentValue() : cond.getLabel(),
				cond.isSatisfied() ? CHECK_ICON : CROSS_ICON,
				SwingConstants.LEFT
			);
			left.setForeground(isChargeWarn ? MISSING_RED : Color.WHITE);
			left.setFont(left.getFont().deriveFont(isChargeWarn ? Font.BOLD : Font.PLAIN, 10.8f));
			row.add(left, BorderLayout.CENTER);

			if (!isChargeWarn)
			{
				String rightText = cond.isSatisfied()
					? cond.getCurrentValue()
					: (cond.getCurrentValue() + " / " + cond.getExpectedValue());
				JLabel right = new JLabel(rightText);
				right.setForeground(cond.isSatisfied() ? READY_GREEN : MISSING_RED);
				right.setFont(right.getFont().deriveFont(Font.BOLD, 10.5f));
				row.add(right, BorderLayout.EAST);
			}

			card.add(row);
			card.add(Box.createVerticalStrut(3));
		}

		return card;
	}

	private JPanel buildRemindersCard(ChecklistEvaluation eval)
	{
		String checklistId = eval.getChecklist().getId();
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(SURFACE_CARD);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(eval.getRemindersChecked() == eval.getRemindersTotal() ? new Color(40, 118, 76) : WARN_GOLD),
			new EmptyBorder(7, 8, 7, 8)
		));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);

		JPanel headerRow = new JPanel(new BorderLayout(4, 0));
		headerRow.setOpaque(false);
		headerRow.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel header = new JLabel("Manual Reminders");
		header.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		header.setFont(header.getFont().deriveFont(Font.BOLD, 10.5f));
		headerRow.add(header, BorderLayout.WEST);

		JPanel remActions = new JPanel(new GridLayout(1, 2, 3, 0));
		remActions.setOpaque(false);
		JButton allBtn = flatButton("All", PILL_ACTIVE);
		allBtn.setFont(allBtn.getFont().deriveFont(Font.BOLD, 9.5f));
		allBtn.setBorder(new EmptyBorder(2, 5, 2, 5));
		allBtn.addActionListener(e -> plugin.setAllRemindersChecked(checklistId, true));
		JButton resetBtn = flatButton("Reset", SURFACE_ELEVATED);
		resetBtn.setFont(resetBtn.getFont().deriveFont(Font.BOLD, 9.5f));
		resetBtn.setBorder(new EmptyBorder(2, 5, 2, 5));
		resetBtn.addActionListener(e -> plugin.setAllRemindersChecked(checklistId, false));
		remActions.add(allBtn);
		remActions.add(resetBtn);
		headerRow.add(remActions, BorderLayout.EAST);
		card.add(headerRow);
		card.add(Box.createVerticalStrut(5));

		for (ReminderCheck rem : eval.getReminders())
		{
			JPanel remRow = new JPanel(new BorderLayout(5, 0));
			remRow.setOpaque(false);
			remRow.setBorder(new EmptyBorder(2, 0, 2, 0));
			remRow.setAlignmentX(Component.LEFT_ALIGNMENT);
			remRow.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

			JLabel iconLbl = new JLabel(rem.isChecked() ? BOX_CHECKED_ICON : BOX_EMPTY_ICON);
			iconLbl.setVerticalAlignment(SwingConstants.TOP);
			iconLbl.setBorder(new EmptyBorder(1, 0, 0, 0));
			remRow.add(iconLbl, BorderLayout.WEST);

			JTextArea textArea = wrappingText(rem.getText(), rem.isChecked() ? READY_GREEN : Color.WHITE, 11f);
			textArea.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			remRow.add(textArea, BorderLayout.CENTER);

			MouseAdapter toggleClick = new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					plugin.toggleReminder(checklistId, rem.getText());
				}
			};
			remRow.addMouseListener(toggleClick);
			iconLbl.addMouseListener(toggleClick);
			textArea.addMouseListener(toggleClick);
			card.add(remRow);
		}

		return card;
	}

	private JPanel buildItemsSection(ChecklistEvaluation eval)
	{
		JPanel container = new JPanel();
		container.setLayout(new BoxLayout(container, BoxLayout.Y_AXIS));
		container.setOpaque(false);
		container.setAlignmentX(Component.LEFT_ALIGNMENT);

		PlayerLoadoutSnapshot snap = plugin.getLatestSnapshot();
		boolean showOptional = config.showOptionalItemsInPanel();
		int hiddenOptional = 0;
		int hiddenSatisfied = 0;
		int rendered = 0;

		for (ItemEvaluation itemEval : eval.getItemsSortedMissingFirst())
		{
			if (itemEval.getItem().isOptional() && !showOptional)
			{
				hiddenOptional++;
				continue;
			}
			if (missingOnlyFilter && itemEval.isSatisfied())
			{
				hiddenSatisfied++;
				continue;
			}
			container.add(buildItemCard(itemEval, snap));
			container.add(Box.createVerticalStrut(4));
			rendered++;
		}

		if (eval.getItems().isEmpty())
		{
			JLabel empty = new JLabel("No items in this checklist yet.");
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			empty.setBorder(new EmptyBorder(6, 4, 6, 4));
			container.add(empty);
		}
		else if (rendered == 0 && missingOnlyFilter)
		{
			JLabel allSet = new JLabel("All visible items are satisfied.");
			allSet.setForeground(READY_GREEN);
			allSet.setFont(allSet.getFont().deriveFont(Font.BOLD, 11f));
			allSet.setBorder(new EmptyBorder(6, 4, 6, 4));
			container.add(allSet);
		}

		if (hiddenSatisfied > 0 || hiddenOptional > 0)
		{
			List<String> parts = new ArrayList<>();
			if (hiddenSatisfied > 0)
			{
				parts.add(hiddenSatisfied + " satisfied hidden");
			}
			if (hiddenOptional > 0)
			{
				parts.add(hiddenOptional + " optional hidden");
			}
			JLabel hidden = new JLabel(String.join(" | ", parts));
			hidden.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			hidden.setFont(hidden.getFont().deriveFont(10f));
			hidden.setBorder(new EmptyBorder(2, 2, 2, 2));
			container.add(hidden);
		}

		return container;
	}

	private JPanel buildItemCard(ItemEvaluation itemEval, @Nullable PlayerLoadoutSnapshot snap)
	{
		ChecklistItem item = itemEval.getItem();
		ItemStatus status = itemEval.getStatus();

		Color borderColor;
		Color bgColor;
		Color qtyColor;
		switch (status)
		{
			case SATISFIED:
				borderColor = new Color(40, 118, 76);
				bgColor = SURFACE_CARD;
				qtyColor = READY_GREEN;
				break;
			case PARTIAL:
				borderColor = WARN_GOLD;
				bgColor = SURFACE_CARD;
				qtyColor = WARN_GOLD;
				break;
			case MISSING:
				borderColor = new Color(156, 62, 66);
				bgColor = MISSING_BG;
				qtyColor = MISSING_RED;
				break;
			case OPTIONAL_MISSING:
			default:
				borderColor = BORDER_SUBTLE;
				bgColor = SURFACE_CARD;
				qtyColor = ColorScheme.LIGHT_GRAY_COLOR;
				break;
		}

		JPanel card = new JPanel(new GridBagLayout());
		card.setBackground(bgColor);
		card.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(borderColor),
			new EmptyBorder(5, 6, 5, 7)
		));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);

		GridBagConstraints gbc = new GridBagConstraints();
		gbc.gridy = 0;
		gbc.insets = new Insets(0, 0, 0, 6);
		gbc.anchor = GridBagConstraints.WEST;

		JLabel iconLabel = new JLabel();
		iconLabel.setPreferredSize(new Dimension(28, 24));
		iconLabel.setHorizontalAlignment(SwingConstants.CENTER);
		int iconId = itemEval.getRecommendedItemId() > 0 ? itemEval.getRecommendedItemId() : item.getDisplayIconId();
		if (iconId > 0)
		{
			AsyncBufferedImage img = itemManager.getImage(iconId);
			img.addTo(iconLabel);
		}
		gbc.gridx = 0;
		gbc.weightx = 0;
		card.add(iconLabel, gbc);

		JPanel mid = new JPanel();
		mid.setLayout(new BoxLayout(mid, BoxLayout.Y_AXIS));
		mid.setOpaque(false);

		JTextArea labelArea = wrappingText(item.getLabel(), Color.WHITE, 11.5f);
		labelArea.setFont(labelArea.getFont().deriveFont(Font.BOLD, 11.5f));
		mid.add(labelArea);

		String recName = item.resolveGroup() != null ? plugin.getCachedItemName(itemEval.getRecommendedItemId()) : null;
		boolean showBankCount = snap != null && snap.isLoggedIn() && !snap.isUltimateIronman()
			&& status != ItemStatus.SATISFIED && itemEval.getInBankCount() > 0;
		JTextArea recArea = null;

		if (recName != null && !recName.isEmpty() && snap != null && snap.isLoggedIn())
		{
			boolean multiPieceOutfit = item.getScope() == ItemSlotScope.EQUIPMENT && itemEval.getRequiredCount() > 1;
			boolean optionalNotOwnedInBank = status == ItemStatus.OPTIONAL_MISSING
				&& !snap.isUltimateIronman()
				&& !snap.getBankCounts().isEmpty()
				&& itemEval.getInBankCount() == 0;

			if (multiPieceOutfit)
			{
				if (status == ItemStatus.SATISFIED)
				{
					recArea = wrappingText("Full set equipped", READY_GREEN, 10f);
				}
				else if (itemEval.getOwnedCount() > 0)
				{
					recArea = wrappingText("Equipped " + itemEval.getOwnedCount() + "/" + itemEval.getRequiredCount(), WARN_GOLD, 10f);
				}
				else if (itemEval.isRecommendedFromBank())
				{
					recArea = wrappingText("Pieces in bank: " + itemEval.getInBankCount(), BANK_BLUE, 10f);
				}
				else if (optionalNotOwnedInBank)
				{
					recArea = wrappingText("Not in bank", ColorScheme.LIGHT_GRAY_COLOR, 10f);
				}
			}
			else if (optionalNotOwnedInBank)
			{
				recArea = wrappingText("Not in bank (" + recName + ")", ColorScheme.LIGHT_GRAY_COLOR, 10f);
			}
			else
			{
				String prefix;
				Color recColor;
				if (status == ItemStatus.SATISFIED)
				{
					prefix = "Using: ";
					recColor = READY_GREEN;
				}
				else if (itemEval.isRecommendedFromBank())
				{
					prefix = "Bank BiS: ";
					recColor = BANK_BLUE;
				}
				else
				{
					prefix = "BiS: ";
					recColor = WARN_GOLD;
				}
				recArea = wrappingText(prefix + recName, recColor, 10f);
			}
			if (recArea != null)
			{
				mid.add(recArea);
			}
		}

		StringBuilder sub = new StringBuilder();
		sub.append(item.getScope() != null ? item.getScope().getDisplayName() : "Any");
		if (item.isCheckRunePouch())
		{
			sub.append(" + Pouch");
		}
		if (item.isOptional())
		{
			sub.append(" | Optional");
		}
		if (showBankCount)
		{
			sub.append(" | Bank: ").append(itemEval.getInBankCount());
		}

		JLabel subLbl = new JLabel(sub.toString());
		subLbl.setForeground(showBankCount ? BANK_BLUE : ColorScheme.LIGHT_GRAY_COLOR);
		subLbl.setFont(subLbl.getFont().deriveFont(10f));
		subLbl.setAlignmentX(Component.LEFT_ALIGNMENT);
		mid.add(subLbl);

		gbc.gridx = 1;
		gbc.weightx = 1.0;
		gbc.fill = GridBagConstraints.HORIZONTAL;
		card.add(mid, gbc);

		String statusText;
		if (itemEval.isSatisfiedByUnlimitedVariant())
		{
			statusText = "OK";
		}
		else if (status == ItemStatus.SATISFIED)
		{
			statusText = itemEval.getOwnedCount() + "/" + itemEval.getRequiredCount();
		}
		else if (status == ItemStatus.OPTIONAL_MISSING)
		{
			statusText = itemEval.getOwnedCount() > 0
				? (itemEval.getOwnedCount() + "/" + itemEval.getRequiredCount())
				: ("x" + itemEval.getRequiredCount());
		}
		else
		{
			statusText = itemEval.getOwnedCount() + "/" + itemEval.getRequiredCount();
		}

		JLabel rightLbl = new JLabel(statusText);
		rightLbl.setForeground(qtyColor);
		rightLbl.setFont(rightLbl.getFont().deriveFont(Font.BOLD, 11f));
		gbc.gridx = 2;
		gbc.weightx = 0;
		gbc.fill = GridBagConstraints.NONE;
		gbc.insets = new Insets(0, 4, 0, 0);
		gbc.anchor = GridBagConstraints.EAST;
		card.add(rightLbl, gbc);

		if (status != ItemStatus.SATISFIED)
		{
			String copyTarget = (recName != null && !recName.isEmpty()) ? recName : item.getLabel();
			Cursor hand = Cursor.getPredefinedCursor(Cursor.HAND_CURSOR);
			card.setCursor(hand);
			labelArea.setCursor(hand);
			if (recArea != null)
			{
				recArea.setCursor(hand);
			}
			card.setToolTipText("Click to copy \"" + copyTarget + "\" for bank search");
			MouseAdapter copyClick = new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					copyTextToClipboard(copyTarget);
				}
			};
			card.addMouseListener(copyClick);
			mid.addMouseListener(copyClick);
			labelArea.addMouseListener(copyClick);
			if (recArea != null)
			{
				recArea.addMouseListener(copyClick);
			}
			subLbl.addMouseListener(copyClick);
			iconLabel.addMouseListener(copyClick);
			rightLbl.addMouseListener(copyClick);
		}

		return card;
	}

