	private void promptCaptureLoadout()
	{
		PlayerLoadoutSnapshot snap = plugin.getLatestSnapshot();
		if (snap == null || !snap.isLoggedIn())
		{
			JOptionPane.showMessageDialog(
				this,
				"Log in to OSRS first so Trip Checklist can read your worn gear, inventory, and spellbook.",
				"Not Logged In",
				JOptionPane.INFORMATION_MESSAGE
			);
			return;
		}

		JTextField nameInput = new JTextField("My Loadout");
		JComboBox<ChecklistCategory> catInput = new JComboBox<>(ChecklistCategory.values());
		catInput.setSelectedItem(ChecklistCategory.CUSTOM);

		JPanel form = new JPanel(new GridLayout(0, 1, 0, 4));
		form.add(new JLabel("Checklist Name:"));
		form.add(nameInput);
		form.add(new JLabel("Category:"));
		form.add(catInput);

		int result = JOptionPane.showConfirmDialog(
			this,
			form,
			"Capture Current Gear & Inventory",
			JOptionPane.OK_CANCEL_OPTION,
			JOptionPane.PLAIN_MESSAGE
		);
		if (result != JOptionPane.OK_OPTION)
		{
			return;
		}
		String name = nameInput.getText().trim();
		if (name.isEmpty())
		{
			return;
		}
		ChecklistCategory cat = (ChecklistCategory) catInput.getSelectedItem();
		plugin.captureCurrentLoadout(name, cat, captured ->
		{
			categoryFilter = null;
			persistCategoryFilter();
			refresh();
		});
	}

