	private void loadPersistedUiFilters()
	{
		String savedCat = configManager.getConfiguration(TripChecklistConfig.GROUP, KEY_CATEGORY_FILTER);
		if (savedCat == null || savedCat.isEmpty() || "ALL".equals(savedCat))
		{
			categoryFilter = null;
		}
		else
		{
			try
			{
				categoryFilter = ChecklistCategory.valueOf(savedCat);
			}
			catch (IllegalArgumentException ex)
			{
				categoryFilter = null;
			}
		}

		String savedMissing = configManager.getConfiguration(TripChecklistConfig.GROUP, KEY_MISSING_ONLY);
		missingOnlyFilter = Boolean.parseBoolean(savedMissing);
	}

	private void persistCategoryFilter()
	{
		configManager.setConfiguration(
			TripChecklistConfig.GROUP,
			KEY_CATEGORY_FILTER,
			categoryFilter == null ? "ALL" : categoryFilter.name()
		);
	}

