	private static final class StarIcon implements Icon
	{
		private final boolean filled;
		private final Color color;

		StarIcon(boolean filled, Color color)
		{
			this.filled = filled;
			this.color = color;
		}

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(color);
			Polygon star = new Polygon();
			double cx = x + 6.5;
			double cy = y + 6.5;
			for (int i = 0; i < 10; i++)
			{
				double angle = Math.toRadians(-90 + i * 36);
				double radius = (i % 2 == 0) ? 6.0 : 2.6;
				star.addPoint((int) Math.round(cx + Math.cos(angle) * radius), (int) Math.round(cy + Math.sin(angle) * radius));
			}
			if (filled)
			{
				g2.fillPolygon(star);
			}
			else
			{
				g2.drawPolygon(star);
			}
			g2.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return 13;
		}

		@Override
		public int getIconHeight()
		{
			return 13;
		}
	}

