public class BuiltInPresetsTest
{
	@Test
	public void everyPresetHasUniqueIdAndValidItems()
	{
		List<TripChecklist> presets = BuiltInPresets.all();
		assertTrue("Expected at least 27 curated built-in presets", presets.size() >= 27);

		Set<String> ids = new HashSet<>();
		Set<ChecklistCategory> coveredCategories = EnumSet.noneOf(ChecklistCategory.class);
		for (TripChecklist preset : presets)
		{
			assertNotNull(preset.getId());
			assertTrue("Duplicate preset id: " + preset.getId(), ids.add(preset.getId()));
			assertTrue("Built-in preset must set builtIn=true: " + preset.getId(), preset.isBuiltIn());
			assertNotNull(preset.getName());
			assertFalse(preset.getName().trim().isEmpty());
			assertNotNull(preset.getCategory());
			coveredCategories.add(preset.getCategory());
			assertNotNull(preset.getRequiredSpellbook());
			assertTrue("minFreeSlots out of range on " + preset.getId(),
				preset.getMinFreeSlots() >= 0 && preset.getMinFreeSlots() <= PlayerLoadoutSnapshot.INVENTORY_CAPACITY);
			assertNotNull(preset.getItems());
			assertFalse("Preset must contain items: " + preset.getId(), preset.getItems().isEmpty());

			if (preset.getReminders() != null)
			{
				for (String reminder : preset.getReminders())
				{
					assertNotNull(reminder);
					assertFalse("Blank reminder on " + preset.getId(), reminder.trim().isEmpty());
				}
			}

			for (ChecklistItem item : preset.getItems())
			{
				assertNotNull(item.getLabel());
				assertFalse(item.getLabel().trim().isEmpty());
				assertTrue("Quantity must be positive on " + item.getLabel(), item.getQuantity() >= 1);
				assertTrue("Display icon ID must be valid on " + item.getLabel(), item.getDisplayIconId() > 0);
				assertFalse("Item must match at least one item ID: " + item.getLabel(), item.getMatchingItemIds().isEmpty());
				if (item.getGroupId() != null)
				{
					assertNotNull("Unknown ItemGroup on " + item.getLabel(), item.resolveGroup());
				}
			}
		}

		for (ChecklistCategory cat : ChecklistCategory.values())
		{
			if (cat != ChecklistCategory.CUSTOM)
			{
				assertTrue("Expected built-in presets for category " + cat, coveredCategories.contains(cat));
			}
		}
	}

