	@Test
	public void verifiesSlotScopeSmartGroupsUnlimitedVariantsAndRunePouch()
	{
		TripChecklist checklist = TripChecklist.builder()
			.id("custom-test")
			.name("Burst + Herb Hybrid")
			.category(ChecklistCategory.SLAYER)
			.requiredSpellbook(SpellbookType.ANCIENT)
			.minPrayerPercent(90)
			.minRunEnergy(70)
			.minSpecPercent(100)
			.items(Arrays.asList(
				ChecklistItem.group("Slayer Helmet", ItemGroup.SLAYER_HELM, 1, ItemSlotScope.EQUIPMENT, false),
				ChecklistItem.group("Prayer Potions", ItemGroup.PRAYER_POTION, 4, ItemSlotScope.INVENTORY, false),
				ChecklistItem.group("Compost", ItemGroup.COMPOST, 8, ItemSlotScope.INVENTORY, false),
				ChecklistItem.rune("Death Runes", ItemID.DEATHRUNE, 500, false),
				ChecklistItem.group("Herb Sack", ItemGroup.HERB_SACK, 1, ItemSlotScope.INVENTORY, true)
			))
			.build();

		Map<Skill, Integer> skills = new EnumMap<>(Skill.class);
		skills.put(Skill.DEFENCE, 70);

		Map<Integer, Integer> invPartial = new HashMap<>();
		invPartial.put(ItemID.SLAYER_HELM_I, 1);
		invPartial.put(ItemID._3DOSEPRAYERRESTORE, 2);
		invPartial.put(ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED, 1);
		invPartial.put(ItemID.BH_RUNE_POUCH, 1);
		invPartial.put(ItemID.DEATHRUNE, 200);

		Map<Integer, Integer> bank = new HashMap<>();
		bank.put(ItemID._4DOSE2RESTORE, 50);

		PlayerLoadoutSnapshot notReadySnap = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.bankOpen(true)
			.activeSpellbook(SpellbookType.STANDARD)
			.prayerPercent(85)
			.runEnergyPercent(95)
			.specEnergyPercent(100)
			.skillLevels(skills)
			.inventoryCounts(invPartial)
			.equipmentCounts(Collections.emptyMap())
			.runePouchCounts(Collections.singletonMap(ItemID.DEATHRUNE, 300))
			.bankCounts(bank)
			.build();

		ChecklistEvaluation eval = ChecklistEvaluator.evaluate(checklist, notReadySnap, true);
		assertFalse(eval.isReady());
		assertEquals(ItemStatus.MISSING, eval.getItems().get(0).getStatus());
		assertEquals(ItemStatus.PARTIAL, eval.getItems().get(1).getStatus());
		assertEquals(2, eval.getItems().get(1).getMissingCount());
		assertEquals(50, eval.getItems().get(1).getInBankCount());
		assertEquals(ItemStatus.SATISFIED, eval.getItems().get(2).getStatus());
		assertTrue("Bottomless compost bucket should satisfy full qty 8", eval.getItems().get(2).isSatisfiedByUnlimitedVariant());
		assertEquals("200 inv + 300 rune pouch death runes satisfy 500", ItemStatus.SATISFIED, eval.getItems().get(3).getStatus());
		assertEquals(ItemStatus.OPTIONAL_MISSING, eval.getItems().get(4).getStatus());

		BankHighlightHint restoreHint = eval.getBankHighlight(ItemID._4DOSE2RESTORE);
		assertNotNull(restoreHint);
		assertEquals(2, restoreHint.getMissingCount());
		assertFalse(restoreHint.isOptional());
		assertNull("Satisfied Death Runes must not be highlighted in bank", eval.getBankHighlight(ItemID.DEATHRUNE));
		assertNull("Satisfied Compost must not be highlighted in bank", eval.getBankHighlight(ItemID.BUCKET_ULTRACOMPOST));

		// Soul Wars imbued Slayer Helm + Open Herb Sack + Ancient Spellbook -> READY
		Map<Integer, Integer> invReady = new HashMap<>(invPartial);
		invReady.remove(ItemID.SLAYER_HELM_I);
		invReady.put(ItemID._4DOSE2RESTORE, 2);
		invReady.put(ItemID.SLAYER_HERB_SACK_OPEN, 1);

		PlayerLoadoutSnapshot readySnap = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.bankOpen(false)
			.activeSpellbook(SpellbookType.ANCIENT)
			.prayerPercent(95)
			.runEnergyPercent(95)
			.specEnergyPercent(100)
			.skillLevels(skills)
			.inventoryCounts(invReady)
			.equipmentCounts(Collections.singletonMap(ItemID.SW_SLAYER_HELM_I_HYDRA, 1))
			.runePouchCounts(Collections.singletonMap(ItemID.DEATHRUNE, 300))
			.bankCounts(bank)
			.build();

		ChecklistEvaluation readyEval = ChecklistEvaluator.evaluate(checklist, readySnap, true);
		assertTrue(readyEval.isReady());
		assertEquals(ItemStatus.SATISFIED, readyEval.getItems().get(4).getStatus());
	}

	@Test
	public void recognizesForestryTwoHandedAxesAndWornForestryKit()
	{
		TripChecklist wcPreset = BuiltInPresets.all().stream()
			.filter(p -> "preset-skilling-woodcutting".equals(p.getId()))
			.findFirst()
			.orElseThrow();

		Map<Integer, Integer> worn = new HashMap<>();
		worn.put(ItemID.DRAGON_AXE_2H, 1);
		worn.put(ItemID.FORESTRY_BASKET_OPEN, 1);
		worn.put(ItemID.FORESTRY_LUMBERJACK_HAT, 1);
		worn.put(ItemID.FORESTRY_LUMBERJACK_TOP, 1);
		worn.put(ItemID.FORESTRY_LUMBERJACK_LEGS, 1);
		worn.put(ItemID.FORESTRY_LUMBERJACK_BOOTS, 1);

		Map<Integer, Integer> inv = new HashMap<>();
		inv.put(ItemID.KNIFE, 1);
		inv.put(ItemID.TINDERBOX, 1);

		PlayerLoadoutSnapshot choppingSnap = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.skillLevels(Collections.singletonMap(Skill.WOODCUTTING, 65))
			.equipmentCounts(worn)
			.inventoryCounts(inv)
			.build();

		ChecklistEvaluation eval = ChecklistEvaluator.evaluate(wcPreset, choppingSnap, true);
		assertTrue("Worn Dragon 2h axe should satisfy Woodcutting / Forestry Trip", eval.isReady());
		assertEquals(ItemID.DRAGON_AXE_2H, eval.getItems().get(0).getRecommendedItemId());
		assertEquals("4/4 Forestry outfit pieces must satisfy Lumberjack / Forestry Outfit",
			ItemStatus.SATISFIED, eval.getItems().get(1).getStatus());
		assertEquals(ItemStatus.SATISFIED, eval.getItems().get(2).getStatus());
		assertEquals("Worn Forestry Basket must also satisfy Log / Forestry Basket",
			ItemStatus.SATISFIED, eval.getItems().get(3).getStatus());
		assertEquals("Knife satisfied", ItemStatus.SATISFIED, eval.getItems().get(4).getStatus());
		assertEquals("Tinderbox satisfied", ItemStatus.SATISFIED, eval.getItems().get(5).getStatus());

		// Plain Forestry Kit without Log Basket or Forestry Basket: kit is satisfied, Log Basket falls back to base Log Basket (not Forestry Basket)
		Map<Integer, Integer> plainKitWorn = new HashMap<>();
		plainKitWorn.put(ItemID.RUNE_AXE_2H, 1);
		plainKitWorn.put(ItemID.FORESTRY_KIT, 1);
		plainKitWorn.put(ItemID.RAMBLE_LUMBERJACK_HAT, 1);

		Map<Integer, Integer> partialOutfitBank = new HashMap<>();
		partialOutfitBank.put(ItemID.RAMBLE_LUMBERJACK_HAT, 1);
		partialOutfitBank.put(ItemID.RAMBLE_LUMBERJACK_TOP, 1);
		partialOutfitBank.put(ItemID.RAMBLE_LUMBERJACK_LEGS, 1);

		PlayerLoadoutSnapshot plainKitSnap = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.skillLevels(Collections.singletonMap(Skill.WOODCUTTING, 55))
			.equipmentCounts(plainKitWorn)
			.inventoryCounts(Collections.emptyMap())
			.bankCounts(partialOutfitBank)
			.build();

		ChecklistEvaluation plainEval = ChecklistEvaluator.evaluate(wcPreset, plainKitSnap, true);
		assertTrue("Worn Rune 2h axe + plain Forestry Kit should be READY", plainEval.isReady());
		assertEquals("Already-worn Lumberjack hat in bank must not be highlighted",
			null, plainEval.getBankHighlight(ItemID.RAMBLE_LUMBERJACK_HAT));
		assertNotNull("Unworn Lumberjack top in bank should be highlighted",
			plainEval.getBankHighlight(ItemID.RAMBLE_LUMBERJACK_TOP));
		assertEquals(ItemID.FORESTRY_KIT, plainEval.getItems().get(2).getRecommendedItemId());
		assertEquals(ItemStatus.SATISFIED, plainEval.getItems().get(2).getStatus());
		assertEquals(ItemStatus.OPTIONAL_MISSING, plainEval.getItems().get(3).getStatus());
		assertEquals("Unowned combined Forestry Basket must not be pushed over base Log Basket",
			ItemID.LOG_BASKET_OPEN, plainEval.getItems().get(3).getRecommendedItemId());

		// Worn Fish Sack Barrel + Angler outfit satisfies Fishing preset
		TripChecklist fishPreset = BuiltInPresets.all().stream()
			.filter(p -> "preset-skilling-fishing".equals(p.getId()))
			.findFirst()
			.orElseThrow();
		Map<Integer, Integer> fishWorn = new HashMap<>();
		fishWorn.put(ItemID.DRAGON_HARPOON, 1);
		fishWorn.put(ItemID.FISH_SACK_BARREL_OPEN, 1);
		PlayerLoadoutSnapshot fishSnap = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.skillLevels(Collections.singletonMap(Skill.FISHING, 70))
			.equipmentCounts(fishWorn)
			.build();
		ChecklistEvaluation fishEval = ChecklistEvaluator.evaluate(fishPreset, fishSnap, true);
		assertTrue(fishEval.isReady());
		assertEquals(ItemStatus.SATISFIED, fishEval.getItems().get(2).getStatus());
		assertEquals(ItemID.FISH_SACK_BARREL_OPEN, fishEval.getItems().get(2).getRecommendedItemId());

		// Daeyalt Essence satisfies Runecrafting preset
		TripChecklist rcPreset = BuiltInPresets.all().stream()
			.filter(p -> "preset-skilling-runecraft".equals(p.getId()))
			.findFirst()
			.orElseThrow();
		Map<Integer, Integer> rcInv = new HashMap<>();
		rcInv.put(ItemID.RCU_POUCH_COLOSSAL, 1);
		rcInv.put(ItemID.BLANKRUNE_DAEYALT, 25);
		PlayerLoadoutSnapshot rcSnap = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.runEnergyPercent(90)
			.skillLevels(Collections.singletonMap(Skill.RUNECRAFT, 90))
			.inventoryCounts(rcInv)
			.build();
		assertTrue("Colossal pouch + 25 Daeyalt essence should satisfy Runecrafting Trip",
			ChecklistEvaluator.evaluate(rcPreset, rcSnap, true).isReady());
	}

	@Test
	public void accountAwareBisSelectsAndHighlightsOnlyBestUsableOwnedTier()
	{
		TripChecklist combatChecklist = TripChecklist.builder()
			.id("custom-bis-test")
			.name("BiS Selection Test")
			.category(ChecklistCategory.BOSSING)
			.items(Arrays.asList(
				ChecklistItem.group("Axe", ItemGroup.AXE, 1, ItemSlotScope.ANY, false),
				ChecklistItem.group("Melee Weapon", ItemGroup.MELEE_WEAPON, 1, ItemSlotScope.EQUIPMENT, false)
			))
			.build();

		// P2P account with 65 WC, 70 Attack; bank contains unusable Crystal/Scythe + usable Dragon 2h / Whip + junk Bronze / Rune Scim
		Map<Skill, Integer> midP2pSkills = new EnumMap<>(Skill.class);
		midP2pSkills.put(Skill.WOODCUTTING, 65);
		midP2pSkills.put(Skill.ATTACK, 70);
		midP2pSkills.put(Skill.STRENGTH, 70);

		Map<Integer, Integer> richBank = new HashMap<>();
		richBank.put(ItemID.CRYSTAL_AXE_2H, 1);
		richBank.put(ItemID.DRAGON_AXE_2H, 1);
		richBank.put(ItemID.BRONZE_AXE, 1);
		richBank.put(ItemID.SCYTHE_OF_VITUR, 1);
		richBank.put(ItemID.ABYSSAL_WHIP, 1);
		richBank.put(ItemID.RUNE_SCIMITAR, 1);

		PlayerLoadoutSnapshot midP2pSnap = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.bankOpen(true)
			.skillLevels(midP2pSkills)
			.bankCounts(richBank)
			.build();

		ChecklistEvaluation p2pEval = ChecklistEvaluator.evaluate(combatChecklist, midP2pSnap, true);
		ItemEvaluation axeEval = p2pEval.getItems().get(0);
		ItemEvaluation wepEval = p2pEval.getItems().get(1);

		assertEquals(ItemID.DRAGON_AXE_2H, axeEval.getRecommendedItemId());
		assertTrue(axeEval.isRecommendedFromBank());
		assertEquals(ItemID.ABYSSAL_WHIP, wepEval.getRecommendedItemId());
		assertTrue(wepEval.isRecommendedFromBank());

		// Bank highlights must target ONLY Dragon 2h Axe & Abyssal Whip (not unusable Crystal/Scythe or junk Bronze/Rune)
		assertNotNull(p2pEval.getBankHighlight(ItemID.DRAGON_AXE_2H));
		assertNull(p2pEval.getBankHighlight(ItemID.CRYSTAL_AXE_2H));
		assertNull(p2pEval.getBankHighlight(ItemID.BRONZE_AXE));
		assertNotNull(p2pEval.getBankHighlight(ItemID.ABYSSAL_WHIP));
		assertNull(p2pEval.getBankHighlight(ItemID.SCYTHE_OF_VITUR));
		assertNull(p2pEval.getBankHighlight(ItemID.RUNE_SCIMITAR));

		// F2P world with 50 WC, 50 Attack -> must pick F2P Rune Axe (theoretical) and Rune Scimitar (from bank), never P2P items
		Map<Skill, Integer> f2pSkills = new EnumMap<>(Skill.class);
		f2pSkills.put(Skill.WOODCUTTING, 50);
		f2pSkills.put(Skill.ATTACK, 50);

		PlayerLoadoutSnapshot f2pSnap = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(false)
			.bankOpen(true)
			.skillLevels(f2pSkills)
			.bankCounts(richBank)
			.build();

		ChecklistEvaluation f2pEval = ChecklistEvaluator.evaluate(combatChecklist, f2pSnap, true);
		assertEquals("F2P bank has only Bronze axe usable -> pick Bronze axe from bank",
			ItemID.BRONZE_AXE, f2pEval.getItems().get(0).getRecommendedItemId());
		assertEquals("F2P bank has Rune scimitar usable -> pick Rune scimitar over P2P Whip",
			ItemID.RUNE_SCIMITAR, f2pEval.getItems().get(1).getRecommendedItemId());
		assertNotNull(f2pEval.getBankHighlight(ItemID.RUNE_SCIMITAR));
		assertNull(f2pEval.getBankHighlight(ItemID.ABYSSAL_WHIP));
	}

