	@Test
	public void captureLoadoutMapsSmartGroupsAndRunePouchRunes()
	{
		Map<Integer, Integer> worn = Collections.singletonMap(ItemID.SLAYER_HELM_I, 1);
		Map<Integer, Integer> inv = new HashMap<>();
		inv.put(ItemID._4DOSEPRAYERRESTORE, 2);
		inv.put(ItemID._3DOSEPRAYERRESTORE, 1);
		inv.put(ItemID.SPADE, 1);
		inv.put(ItemID.DIVINE_RUNE_POUCH, 1);

		PlayerLoadoutSnapshot snap = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.activeSpellbook(SpellbookType.LUNAR)
			.equipmentCounts(worn)
			.inventoryCounts(inv)
			.runePouchCounts(Collections.singletonMap(ItemID.ASTRALRUNE, 250))
			.build();

		TripChecklist captured = LoadoutCapture.capture("Lunar Slayer", ChecklistCategory.SLAYER, snap, true, id -> "Item " + id);
		assertFalse(captured.isBuiltIn());
		assertEquals(SpellbookType.LUNAR, captured.getRequiredSpellbook());
