		boolean foundPouchAstrals = captured.getItems().stream()
			.anyMatch(i -> i.getItemId() == ItemID.ASTRALRUNE && i.getQuantity() == 250 && i.isCheckRunePouch());
		assertTrue("Expected Rune Pouch astral runes to be captured with checkRunePouch=true", foundPouchAstrals);
	}

	@Test
	public void enforcesMinFreeSlotsAndRangedAmmoSlotCheck()
	{
		TripChecklist wcPreset = BuiltInPresets.all().stream()
			.filter(p -> "preset-skilling-woodcutting".equals(p.getId()))
			.findFirst()
			.orElseThrow();

		PlayerLoadoutSnapshot crowdedSnap = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.freeInventorySlots(6)
			.skillLevels(Collections.singletonMap(Skill.WOODCUTTING, 75))
			.equipmentCounts(Collections.singletonMap(ItemID.DRAGON_AXE, 1))
			.build();

		ChecklistEvaluation crowdedEval = ChecklistEvaluator.evaluate(wcPreset, crowdedSnap, true);
		assertFalse("Fewer free slots than minFreeSlots must block READY", crowdedEval.isReady());
		assertTrue(crowdedEval.getConditions().stream()
			.anyMatch(c -> "Free Inv Slots".equals(c.getLabel()) && !c.isSatisfied()));

		PlayerLoadoutSnapshot spaciousSnap = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.freeInventorySlots(20)
			.skillLevels(Collections.singletonMap(Skill.WOODCUTTING, 75))
			.equipmentCounts(Collections.singletonMap(ItemID.DRAGON_AXE, 1))
			.build();
		assertTrue(ChecklistEvaluator.evaluate(wcPreset, spaciousSnap, true).isReady());

		TripChecklist rangedCheck = TripChecklist.builder()
			.id("custom-ammo-test")
			.name("Ranged Ammo Check")
			.category(ChecklistCategory.BOSSING)
			.checkRangedAmmo(true)
			.items(Collections.singletonList(
				ChecklistItem.group("Ranged Weapon", ItemGroup.RANGED_WEAPON, 1, ItemSlotScope.EQUIPMENT, false)
			))
			.build();

		PlayerLoadoutSnapshot tbowNoArrows = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.equippedWeaponId(ItemID.TWISTED_BOW)
			.equippedAmmoId(-1)
			.equipmentCounts(Collections.singletonMap(ItemID.TWISTED_BOW, 1))
			.build();
		ChecklistEvaluation noAmmoEval = ChecklistEvaluator.evaluate(rangedCheck, tbowNoArrows, true);
		assertFalse("Twisted bow with empty ammo slot must fail Ammo Slot check", noAmmoEval.isReady());
		assertTrue(noAmmoEval.getConditions().stream()
			.anyMatch(c -> "Ammo Slot".equals(c.getLabel()) && !c.isSatisfied()));

		PlayerLoadoutSnapshot tbowWithArrows = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.equippedWeaponId(ItemID.TWISTED_BOW)
			.equippedAmmoId(ItemID.DRAGON_ARROW)
			.equipmentCounts(Collections.singletonMap(ItemID.TWISTED_BOW, 1))
			.build();
		assertTrue("Twisted bow with equipped arrows must pass Ammo Slot check",
			ChecklistEvaluator.evaluate(rangedCheck, tbowWithArrows, true).isReady());

		PlayerLoadoutSnapshot bowfaSelfContained = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.equippedWeaponId(ItemID.BOW_OF_FAERDHINEN_INFINITE)
			.equippedAmmoId(-1)
			.equipmentCounts(Collections.singletonMap(ItemID.BOW_OF_FAERDHINEN_INFINITE, 1))
			.build();
		ChecklistEvaluation bowfaEval = ChecklistEvaluator.evaluate(rangedCheck, bowfaSelfContained, true);
		assertTrue("Bow of faerdhinen should pass Ammo Slot check as self-contained", bowfaEval.isReady());
		assertTrue(bowfaEval.getConditions().stream()
			.anyMatch(c -> "Ammo Slot".equals(c.getLabel()) && c.isSatisfied() && "Self-contained".equals(c.getCurrentValue())));
	}

