			.category(ChecklistCategory.CLUES)
			.items(Arrays.asList(
				ChecklistItem.exact("Spade", ItemID.SPADE, 1, ItemSlotScope.INVENTORY, false),
				ChecklistItem.group("Amulet of Glory", ItemGroup.AMULET_OF_GLORY, 1, ItemSlotScope.ANY, true)
			))
			.build();

		Map<Integer, Integer> inv = new HashMap<>();
		inv.put(ItemID.SPADE, 1);
		inv.put(ItemID.ECTOPHIAL_EMPTY, 1);
		inv.put(ItemID.BOTTOMLESS_COMPOST_BUCKET, 1);
		inv.put(ItemID.AMULET_OF_GLORY, 1);

		PlayerLoadoutSnapshot unchargedSnap = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.inventoryCounts(inv)
			.equipmentCounts(Collections.singletonMap(ItemID.DRAGONFIRE_SHIELD_UNCHARGED, 1))
			.build();

		ChecklistEvaluation warnEval = ChecklistEvaluator.evaluate(clueChecklist, unchargedSnap, true);
		assertFalse("Carried empty/uncharged items must block READY", warnEval.isReady());
		long warningCount = warnEval.getConditions().stream()
			.filter(c -> "Charge Warning".equals(c.getLabel()) && !c.isSatisfied())
			.count();
		assertEquals("Expected 4 charge warnings (Ectophial, Bottomless bucket, DFS, uncharged Glory)", 4, warningCount);

		// Uncharged items in bank only + uncharged Glory on a checklist that does not request Glory -> READY
		TripChecklist plainChecklist = TripChecklist.builder()
			.id("custom-plain")
			.name("Plain Spade")
			.category(ChecklistCategory.CUSTOM)
			.items(Collections.singletonList(
				ChecklistItem.exact("Spade", ItemID.SPADE, 1, ItemSlotScope.INVENTORY, false)
			))
			.build();

		Map<Integer, Integer> cleanInv = new HashMap<>();
		cleanInv.put(ItemID.SPADE, 1);
		cleanInv.put(ItemID.AMULET_OF_GLORY, 1);

		Map<Integer, Integer> unchargedInBank = new HashMap<>();
		unchargedInBank.put(ItemID.ECTOPHIAL_EMPTY, 1);
		unchargedInBank.put(ItemID.DRAGONFIRE_SHIELD_UNCHARGED, 1);

		PlayerLoadoutSnapshot bankOnlySnap = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.inventoryCounts(cleanInv)
			.bankCounts(unchargedInBank)
			.build();

		ChecklistEvaluation cleanEval = ChecklistEvaluator.evaluate(plainChecklist, bankOnlySnap, true);
		assertTrue("Banked uncharged items and unrelated uncharged Glory must not trigger warnings", cleanEval.isReady());
		for (ConditionCheck cond : cleanEval.getConditions())
		{
			assertFalse("No Charge Warning expected", "Charge Warning".equals(cond.getLabel()));
		}
	}

	@Test
	public void requiresManualRemindersAndSortsMissingItemsFirst()
	{
		TripChecklist wtPreset = BuiltInPresets.all().stream()
			.filter(p -> "preset-minigame-wintertodt".equals(p.getId()))
			.findFirst()
			.orElseThrow();

		Map<Integer, Integer> wtInv = new HashMap<>();
		wtInv.put(ItemID.KNIFE, 1);
		wtInv.put(ItemID.HAMMER, 1);
		wtInv.put(ItemID.TINDERBOX, 1);
		wtInv.put(ItemID.JUG_WINE, 6);

		PlayerLoadoutSnapshot wtSnap = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.freeInventorySlots(18)
			.skillLevels(Collections.singletonMap(Skill.WOODCUTTING, 70))
			.equipmentCounts(Collections.singletonMap(ItemID.DRAGON_AXE, 1))
			.inventoryCounts(wtInv)
			.build();

		ChecklistEvaluation uncheckedEval = ChecklistEvaluator.evaluate(wtPreset, wtSnap, true, Collections.emptySet());
		assertFalse("Unchecked manual reminder must block READY", uncheckedEval.isReady());
		assertEquals(0, uncheckedEval.getRemindersChecked());
		assertEquals(1, uncheckedEval.getRemindersTotal());

		ChecklistEvaluation checkedEval = ChecklistEvaluator.evaluate(
			wtPreset,
			wtSnap,
			true,
			Collections.singleton("Wearing 4 pieces of warm clothing")
		);
		assertTrue("Checking the Wintertodt warm clothing reminder must make checklist READY", checkedEval.isReady());
		assertEquals(1, checkedEval.getRemindersChecked());

		// Verify missing-first sort ordering: MISSING -> PARTIAL -> OPTIONAL_MISSING (bank) -> OPTIONAL_MISSING -> SATISFIED
		TripChecklist sortList = TripChecklist.builder()
			.id("custom-sort")
			.name("Sort Order")
			.category(ChecklistCategory.CUSTOM)
			.items(Arrays.asList(
				ChecklistItem.exact("Satisfied Spade", ItemID.SPADE, 1, ItemSlotScope.INVENTORY, false),
				ChecklistItem.exact("Optional No Bank", ItemID.RAKE, 1, ItemSlotScope.INVENTORY, true),
				ChecklistItem.exact("Optional In Bank", ItemID.CHISEL, 1, ItemSlotScope.INVENTORY, true),
				ChecklistItem.exact("Partial Food", ItemID.SHARK, 4, ItemSlotScope.INVENTORY, false),
				ChecklistItem.exact("Missing Rope", ItemID.ROPE, 1, ItemSlotScope.INVENTORY, false)
			))
			.build();

		Map<Integer, Integer> sortInv = new HashMap<>();
		sortInv.put(ItemID.SPADE, 1);
		sortInv.put(ItemID.SHARK, 2);

		PlayerLoadoutSnapshot sortSnap = PlayerLoadoutSnapshot.builder()
			.loggedIn(true)
			.membersWorld(true)
			.inventoryCounts(sortInv)
			.bankCounts(Collections.singletonMap(ItemID.CHISEL, 1))
			.build();

		List<ItemEvaluation> sorted = ChecklistEvaluator.evaluate(sortList, sortSnap, true).getItemsSortedMissingFirst();
		assertEquals("Missing Rope", sorted.get(0).getItem().getLabel());
		assertEquals("Partial Food", sorted.get(1).getItem().getLabel());
		assertEquals("Optional In Bank", sorted.get(2).getItem().getLabel());
		assertEquals("Optional No Bank", sorted.get(3).getItem().getLabel());
		assertEquals("Satisfied Spade", sorted.get(4).getItem().getLabel());
	}

	@Test
	public void encodesAndDecodesPerAccountBankCacheSafely()
	{
		Map<Integer, Integer> bank = new HashMap<>();
		bank.put(ItemID.ABYSSAL_WHIP, 1);
		bank.put(ItemID.SHARK, 450);
		bank.put(ItemID.DRAGON_AXE, 0);
		bank.put(-5, 10);

		String encoded = TripChecklistPlugin.encodeBankCounts(bank);
		Map<Integer, Integer> decoded = TripChecklistPlugin.decodeBankCounts(encoded);
		assertEquals(2, decoded.size());
		assertEquals(Integer.valueOf(1), decoded.get(ItemID.ABYSSAL_WHIP));
		assertEquals(Integer.valueOf(450), decoded.get(ItemID.SHARK));

		Map<Integer, Integer> resilient = TripChecklistPlugin.decodeBankCounts("bad,12:nope,:5,4151:3,995:-2");
		assertEquals(1, resilient.size());
		assertEquals(Integer.valueOf(3), resilient.get(4151));
		assertTrue(TripChecklistPlugin.decodeBankCounts("").isEmpty());
		assertTrue(TripChecklistPlugin.decodeBankCounts(null).isEmpty());
	}

	@Test
	public void autoCompleteBehaviorMatchesBankCloseAndImmediateTransitions()
	{
		// Default mode: closes ONLY on bank open -> closed while READY
		assertTrue(TripChecklistPlugin.shouldAutoComplete(
			TripChecklistConfig.OnReadyBehavior.AUTO_CLOSE_ON_BANK_CLOSE, true, false, true, true));
		assertFalse("Stay open while bank is still open so player can grab optional items",
			TripChecklistPlugin.shouldAutoComplete(
				TripChecklistConfig.OnReadyBehavior.AUTO_CLOSE_ON_BANK_CLOSE, true, true, false, true));
		assertFalse("Stay open when becoming READY outside bank",
			TripChecklistPlugin.shouldAutoComplete(
				TripChecklistConfig.OnReadyBehavior.AUTO_CLOSE_ON_BANK_CLOSE, false, false, false, true));
		assertFalse("Never close when not READY",
			TripChecklistPlugin.shouldAutoComplete(
				TripChecklistConfig.OnReadyBehavior.AUTO_CLOSE_ON_BANK_CLOSE, true, false, false, false));

		// Manual mode: never auto-closes
		assertFalse(TripChecklistPlugin.shouldAutoComplete(
			TripChecklistConfig.OnReadyBehavior.MANUAL_ONLY, true, false, false, true));

		// Immediate mode: closes on not-ready -> ready transition, not when opening an already-ready checklist
		assertTrue(TripChecklistPlugin.shouldAutoComplete(
			TripChecklistConfig.OnReadyBehavior.AUTO_CLOSE_IMMEDIATELY, true, true, false, true));
		assertFalse(TripChecklistPlugin.shouldAutoComplete(
			TripChecklistConfig.OnReadyBehavior.AUTO_CLOSE_IMMEDIATELY, false, false, true, true));
	}
}

package com.tripchecklist;

import com.tripchecklist.data.BuiltInPresets;
import com.tripchecklist.data.ChecklistCategory;
import com.tripchecklist.data.SpellbookType;
import com.tripchecklist.data.TripChecklist;
import com.tripchecklist.logic.ChecklistSerializer;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ChecklistSerializerTest
{
	private final ChecklistSerializer serializer = new ChecklistSerializer(RuneLiteAPI.GSON);

	@Test
	public void roundTripsCustomChecklistsAndSingleExportImport()
	{
		TripChecklist preset = BuiltInPresets.all().get(0);
		String exported = serializer.exportSingleJson(preset);
		assertTrue(exported.contains("Herb Run"));

		TripChecklist imported = serializer.importSingleJson(exported);
		assertFalse("Imported checklist must always become custom (builtIn=false)", imported.isBuiltIn());
		assertTrue(imported.getId().startsWith("custom-"));
		assertEquals(preset.getName(), imported.getName());
		assertEquals(preset.getItems().size(), imported.getItems().size());

		String listJson = serializer.serializeCustomList(Collections.singletonList(imported));
		List<TripChecklist> restored = serializer.deserializeCustomList(listJson);
		assertEquals(1, restored.size());
		assertEquals(imported.getId(), restored.get(0).getId());
		assertEquals(imported.getItems().size(), restored.get(0).getItems().size());
	}

	@Test
	public void handlesMalformedAndOutOfRangeJsonSafely()
	{
		assertTrue(serializer.deserializeCustomList("").isEmpty());
		assertTrue(serializer.deserializeCustomList("not valid json").isEmpty());

		TripChecklist clamped = serializer.importSingleJson(
			"{\"name\":\"Clamped\",\"category\":\"BOSSING\",\"requiredSpellbook\":\"ANCIENT\",\"minPrayerPercent\":150,\"minRunEnergy\":-20,\"minFreeSlots\":50,\"checkRangedAmmo\":true,\"reminders\":[\"Set quick-prayers\",\"  \",\"Check cannon\"],\"items\":[]}"
		);
		assertEquals(ChecklistCategory.BOSSING, clamped.getCategory());
		assertEquals(SpellbookType.ANCIENT, clamped.getRequiredSpellbook());
		assertEquals(100, clamped.getMinPrayerPercent());
		assertEquals(0, clamped.getMinRunEnergy());
		assertEquals(28, clamped.getMinFreeSlots());
		assertTrue(clamped.isCheckRangedAmmo());
		assertEquals(Arrays.asList("Set quick-prayers", "Check cannon"), clamped.getReminders());

		String reserialized = serializer.serializeCustomList(Collections.singletonList(clamped));
		List<TripChecklist> restored = serializer.deserializeCustomList(reserialized);
		assertEquals(1, restored.size());
		assertEquals(28, restored.get(0).getMinFreeSlots());
		assertTrue(restored.get(0).isCheckRangedAmmo());
		assertEquals(Arrays.asList("Set quick-prayers", "Check cannon"), restored.get(0).getReminders());
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsEmptySingleImport()
	{
		serializer.importSingleJson("   ");
	}
}

